insert into public.academy_course_structures
    (app_slug, tier, structure, content_version)
insert into public.academy_quiz_questions
    (app_slug, tier, scope, module_key, ord, prompt, options, answer_index, explanation)
values
  ('corrosion', 'advanced', 'module', 'm01-what-this-module-holds-back', 1, '`HELD_FOR_LITERATURE` carries 11 items and `NOT_PROVIDED` carries 8. An inspection interval appears on one of them. Which list, and what does the difference commit the engine to?', '["`HELD_FOR_LITERATURE`, because the interval is already computed from the remaining life and only the risk basis underneath it is unsourced in this repository.", "`NOT_PROVIDED`, which is the weaker of the two: the entry is a placeholder the module intends to fill in as soon as an inspection standard is vendored beside it.", "`NOT_PROVIDED`, which is the stronger statement of the two: an interval is outside the scope of the module altogether rather than a number waiting for a source to turn up.", "Both lists at once, because an item that has no source and no implementation is entered twice so that a caller reading either one of them still finds it."]'::jsonb, 2, 'Held means the number is in the code and its source is nowhere in the repository. Not provided means the quantity is absent from the scope, and an inspection interval, a minimum or retirement thickness and a fitness-for-service assessment are all on that second list.'),
  ('corrosion', 'advanced', 'module', 'm01-what-this-module-holds-back', 2, 'The withdrawn sour-service severity region is not on `HELD_FOR_LITERATURE`, and `NOT_PROVIDED` names it marked withdrawn. Why is it not on the held list?', '["It is not waiting for a source. The claim was withdrawn outright, and the engine also reports that absence through `regionProvided` and `materialGuidanceProvided`.", "It sits on a third exported list of withdrawn features, which the whole screening door returns alongside the other two so that a caller can render all three of them together.", "It is held rather than listed, because the region expression still runs on every screening and only the two standard names were stripped out of the strings it returns.", "It came off both lists when the threshold value was kept, since a module that still prints a screening threshold is still classifying severity at that threshold."]'::jsonb, 0, 'Both fields are false today and will stay false, so the absence arrives as a field and a caller cannot read it as an unset property. The region function is not exported and neither standard name appears anywhere in the 783 lines of the engine source.'),
  ('corrosion', 'advanced', 'module', 'm01-what-this-module-holds-back', 3, 'The engine''s own eleven-item held list names three of these four numbers. Which one does it not name?', '["The fugacity pressure cap of 250.000000000000 bar, above which this engine carries the coefficient flat and says in a note that it is doing so.", "The Blasius coefficient of 0.046000000000, which sets this module''s friction factor on its turbulent branch.", "The moderate band of 50.000000000000 Pa, the lower of the two wall shear thresholds.", "The bar to psia factor of 14.503773800722, which follows from the definition of the bar and of the pound-force."]'::jsonb, 3, 'The eleven items are the de Waard-Milliams constants, the scale placement question, the scale constants, the pH slope and reference, the 250 bar cap, the H2S threshold, the two transition ratios, the two shear thresholds, the category bands, the Blasius pair with the Reynolds 4000 switch, and three absent criteria. The engine exports the conversion factor as `BAR_TO_PSIA` and the digest measures it as the psia reported for exactly 1 bar. The Pipeline and Line Sizing course computes its own friction factor and its own Reynolds number on a different correlation with a different transition, so the two will not agree on the same pipe.'),
  ('corrosion', 'advanced', 'module', 'm01-what-this-module-holds-back', 4, 'One entry on the eleven-item held list is a question rather than a constant. Which entry, and what does this module do about it?', '["Whether the pH correction is applied before or after the wetting regime. This module applies the pH correction first, and the order moves the answer whenever the regime is intermittent.", "Whether the protective scale factor multiplies the reaction term or the combined rate. This module multiplies the combined rate, after the series combination has been formed.", "Whether the fugacity coefficient reaches H2S as well as CO2. This module applies it to both of them and reports `ph2sFugacityApplied` true on every screening that it runs.", "Whether the corrosion inhibitor credit is taken before or after the wall shear verdict. This module takes the credit first, which is why a stripped film leaves the rate exactly where it was."]'::jsonb, 1, 'The two readings give materially different answers whenever mass transfer controls, which it does at the app''s own defaults, and which of them the published correlation intends is not established here. Nothing downstream of that factor is graded in this course.'),
  ('corrosion', 'advanced', 'module', 'm01-what-this-module-holds-back', 5, 'A paired battery moved fifteen of seventeen constants in the engine and in the oracle together and left the suite green. What does that establish about a suite comparing only those two files?', '["A constant living in both cannot be validated by comparing them, because the gap between the two answers is genuinely zero whatever the constant is set to.", "The tolerances were too loose for paired moves of that size, so the same battery run against a comparison near machine precision would have caught most of the seventeen.", "The oracle was reading its constants out of the engine at run time, and handing it a private copy of each one is what makes the comparison independent again.", "Seventeen constants is too small a battery, and a sweep that walked every constant in the module would have separated the two files on at least one of them."]'::jsonb, 0, 'No tolerance saves a shared constant, because a tighter comparison makes it more invisible rather than less. Thirty constants are pinned instead, each measured out of the engine''s behaviour and compared against a literal in the digest generator, which is a third file, with the golden''s own block as a fourth.'),
  ('corrosion', 'advanced', 'module', 'm01-what-this-module-holds-back', 6, 'A pinned constant agrees with the literal typed in the digest generator. What has that proved, and what does it leave open?', '["That the constant is the published value, since the generator''s literals were transcribed out of the correlation''s own papers.", "That the engine and the golden agree with each other, which is what a pin is for and what the generator records.", "That nobody moved the number quietly. Where the number came from is still held, because a pin compares a measurement against a third copy rather than against a source.", "Nothing whatever, because a literal typed by whoever read the engine is the same file twice over and the pin table decorates a comparison nobody made."]'::jsonb, 2, 'A pin is a weaker instrument than a validation. Thirty constants are pinned that way, with the golden''s own block as a fourth copy, and the digest says plainly that no source for any of them exists in this repository.'),
  ('corrosion', 'advanced', 'module', 'm01-what-this-module-holds-back', 7, 'How does the digest reach the pH reference of 4.000000000000 and the friction branch switch at Reynolds 4000.000000?', '["By reading `PH_REFERENCE` and `SHEAR_SWITCH_RE` off the engine''s own export block, which is why both of them come back at a relative difference of exactly 0.", "By solving the pH correction and the Blasius form algebraically at two points each, in the way the reaction constants and the mass-transfer exponents are both reached.", "By lifting both of them out of the golden''s `heldConstants` block, which is the copy the vendored jest suite cross-pins against its own typed literals.", "By bisecting what the engine returns: the pH at which it stops giving a factor, and the branch name it reports."]'::jsonb, 3, 'Measuring rather than reading an export is deliberate. An export tells you what the module declares and a measurement tells you what it actually uses, and both columns are printed so that a disagreement between them would be visible.'),
  ('corrosion', 'advanced', 'module', 'm01-what-this-module-holds-back', 8, 'The scale constant A measures 2399.999999999998 out of the engine against a literal of 2400.000000000000. Why does the digest print that rather than round it into agreement?', '["The engine genuinely holds 2399.999999999998, and the literal in the generator is the typing error that the pin table exists to find and to report on every rebuild of the digest.", "The gap is floating point arithmetic on a slope taken between two temperatures, and a measurement tidied into agreement with its own expectation has stopped being a measurement.", "The relative difference of 9.474e-16 sits outside the tolerance the pin table applies, so the row prints as a failure and is left where it is for the next repair to resolve.", "The slope is taken where the factor is clamped at one, so the measurement is reading a clamped expression and the last few digits are the clamp arriving in the answer."]'::jsonb, 1, 'The slope is taken at 150 C and 200 C, where the factor is unclamped, because below the onset the engine returns exactly 1 and the slope would be zero. The relative difference is 9.474e-16, which is the arithmetic rather than a disagreement.'),
  ('corrosion', 'advanced', 'module', 'm01-what-this-module-holds-back', 9, 'The engine exports fifteen constants by name and the digest prints a declared column and a measured column for all fifteen. What is the second column for?', '["So a disagreement between what the module declares and what it actually uses would be visible in the table rather than inferred later from a surprising screen.", "So the export can be checked against the golden''s fourth copy, which is the comparison the vendored jest suite runs and which the digest reproduces here for the reader.", "So the sixteen pinned constants that carry no export at all have somewhere to sit, which is why the mass-transfer coefficient and the Blasius pair both appear in that table.", "So the measured value can replace the declared one wherever the two differ, which keeps the digest reporting behaviour in preference to declarations throughout."]'::jsonb, 0, 'Nothing in this module currently separates, and that is a result with a size attached. An export agreeing with a measurement checks the export, a measurement standing alone checks the behaviour, and neither one says where the number came from.'),
  ('corrosion', 'advanced', 'module', 'm01-what-this-module-holds-back', 10, 'The mass-transfer fugacity exponent measures 1.000000000000 with a relative difference of exactly 0. What is being measured there?', '["One of the few constants the golden can genuinely discriminate, because a relative difference of exactly 0 means the oracle reached it by a route the engine does not share.", "A clamp, since an exponent coming back at exactly one is the value this engine substitutes whenever the fugacity argument it was handed arrives outside its own range.", "A property of the form rather than a typed constant. The term is exactly linear in fugacity, so doubling the fugacity doubles the term.", "The engine''s declared export, which reads 1.000000000000 and is compared against a behaviour."]'::jsonb, 2, 'It is reached by the base two logarithm of the doubling ratio in fugacity, and it confirms the shape of the expression rather than the value of a literal. The velocity exponent of 0.800000000000 and the diameter exponent of 0.200000000000 are ordinary fitted constants reached the same way.'),
  ('corrosion', 'advanced', 'module', 'm01-what-this-module-holds-back', 11, 'The golden''s `provenance.published` is false. What follows from that for this course?', '["Its rows are unusable as evidence of anything at all, so this course leans on the engine''s exports and on the pin table and treats the golden file as documentation.", "Its rows need a published case added beside them before the course can ship, and the eleven held items are the list of the cases still waiting to be sourced and vendored.", "Its rows are published in the sense that matters here, since seventeen derivations agreeing to the last bits of a double is what publication would have established anyway.", "Its rows can show the claim was implemented consistently and cannot show the correlation describes steel, so no graded field here is a rate the correlation produced."]'::jsonb, 3, 'No published de Waard-Milliams case, no clause of either sour-service standard and no corrosion rate-band table exists anywhere in this repository. Route independence and the gate''s pins carry the load instead, and a number recalled from memory is not a published datum.'),
  ('corrosion', 'advanced', 'module', 'm01-what-this-module-holds-back', 12, 'Case 7 of the seventeen vendored cases differs from the golden rate at 8.901e-5 against a tolerance of 1e-3, while the other rate differences sit in the last bits of a double. How is that figure read?', '["As a defect on case 7, since sixteen cases reaching machine precision beside one reaching 8.901e-5 is the signature of a route that has drifted out of step with the engine.", "As a size, which is what makes the agreement a result. The digest prints the difference on every case rather than printing a pass.", "As a tolerance far too loose at 1e-3, because a comparison admitting a gap four orders of magnitude above the others will admit whatever the route happens to produce.", "As the fugacity cap arriving, since case 7 is the case whose total pressure sits above 250.000000000000 bar and the coefficient is carried flat from there upward."]'::jsonb, 1, 'Agreement between two separate derivations is a result with a size and the digest prints the size. The combined rate on the same case agrees at 5.458e-16 against a tolerance of 1e-9, so the two columns are checked at two different tolerances on purpose.'),
  ('corrosion', 'advanced', 'module', 'm01-what-this-module-holds-back', 13, 'The route table gives each of the eight oracle routes a cannot-check column. What does the wall shear route fail to check?', '["The Blasius pair, the laminar constant and the branch switch, because a momentum balance over a stated length reaches the shear without touching any of them.", "The film-stripping threshold of 100.000000000000 Pa and the moderate band of 50.000000000000 Pa.", "This module''s Reynolds number, since a momentum balance taken over a stated length arrives at the shear without ever forming a Reynolds number of its own along the way.", "Nothing whatever, because the pipe force balance is checked as an identity and an identity that holds covers every constant sitting in the branch beneath it."]'::jsonb, 0, 'A route checks what it derives independently. The film onset route cannot check the three scale constants, the mole-fraction ratio route cannot check the two boundary ratios, and the sour comparison cannot check the threshold value. The Pipeline and Line Sizing course computes its own friction factor and its own Reynolds number with a different correlation and a different transition.'),
  ('corrosion', 'advanced', 'module', 'm01-what-this-module-holds-back', 14, 'Four of the eight routes carry nothing in the cannot-check column: the series combination, the corrosion inhibitor time average, the remaining life and the allowance shortfall. What do those four share?', '["Each is checked against the golden at the tighter of the two tolerances, so a shared constant would surface as a difference that the looser column would have absorbed.", "Each is reached by bisection rather than by a closed form, and a bisection converges on the engine''s own answer without ever evaluating the engine''s own constants.", "Each is arithmetic with no fitted constant inside it, where each of the other four reaches a correlation that carries one.", "Each appears in the golden''s `heldConstants` block as well as in the route table."]'::jsonb, 2, 'That is the same property that decides which of the eighteen graded fields this course can carry. The four routes that do carry an entry in that column each reach a correlation with held constants inside it.'),
  ('corrosion', 'advanced', 'module', 'm01-what-this-module-holds-back', 15, 'The oracle forms the H2S to CO2 ratio from mole fractions rather than from partial pressures. What does that route catch which writing the engine''s own ratio out again could not?', '["The two boundary ratios of 0.002000000000 and 0.050000000000, which is why this is the one place in the file where the regime words are validated rather than merely pinned.", "An H2S partial pressure built from the total pressure with the mole fraction dropped, and an H2S partial pressure fed a CO2 fugacity where the partial pressure belongs.", "The fugacity pressure cap reaching the ratio above 250.000000000000 bar, which is the single pressure at which the two routes to the ratio would visibly separate.", "A ratio formed with its two arguments the wrong way round, since the mole-fraction form is the only one of the two that is not symmetric in the inputs it is handed."]'::jsonb, 1, 'Both arguments are the total pressure times a mole fraction, so the pressure divides out and the ratio equals the ratio of the mole fractions at any pressure whatsoever. The difference column against the partial-pressure route is zero at every pressure in the table.'),
  ('corrosion', 'advanced', 'module', 'm02-what-the-module-does-not-have', 1, 'A reader arrives at this studio with an inspection question. What does the engine have for it, and what does it lack?', '["A remaining life with an interval derived from it by the design life, and the risk basis underneath that interval is the one part `NOT_PROVIDED` records as absent.", "A remaining life against a stated corrosion allowance. It has no interval, no risk basis and no inspection standard of any kind.", "A wall shear with a film risk word beside it, from which the studio schedules the next look, leaving only the retirement thickness for the reader to supply.", "Nothing whatever, which is why an inspection interval sits in `NOT_PROVIDED` beside the minimum thickness."]'::jsonb, 1, 'A remaining life and an inspection interval are different quantities. One divides what is left by a rate, the other is a decision about when to look, and the second needs a method the first cannot supply. For the fitness-for-service question the engine has nothing at all.'),
  ('corrosion', 'advanced', 'module', 'm02-what-the-module-does-not-have', 2, 'Most refusals in this module say an input is wrong or missing. What does the refusal on an allowance that is already consumed say instead?', '["That the consumed depth arrived as a negative number, which is the guard the remaining-life door applies before it divides anything at all.", "That the remaining life would come out negative, so the door issues a life of zero years and a failing verdict rather than a number nobody could act on.", "That the corrosion allowance box was left blank, which is the refusal the door also raises for a zero allowance and for an allowance that is not a number.", "That the input is fine and the module is the wrong tool, because a line whose allowance is gone has become an inspection and fitness-for-service question."]'::jsonb, 3, 'The door returns neither a negative life nor a zero one. It says the question has changed, and this module carries no inspection method and no fitness-for-service method of any kind.'),
  ('corrosion', 'advanced', 'module', 'm02-what-the-module-does-not-have', 3, 'This course uses the word integrity narrowly and says so wherever the word appears. What does it mean here?', '["One arithmetic: a corrosion allowance divided by a rate, and nothing beyond that.", "An assessment of whether the line is fit for service, reached from the remaining life and the corrosion allowance the caller supplied together.", "A minimum wall thickness the studio holds the consumed depth against, which is what turns a remaining life into a retirement decision on a real pipe.", "A schedule of when the line should next be inspected, which the studio derives by setting the remaining life against the stated design life."]'::jsonb, 0, 'A remaining life of 36.112878 yr on one stream and 0.161915 yr on another is that division and nothing more. The word invites four expectations the module cannot meet, which is why the narrow reading is stated every time.'),
  ('corrosion', 'advanced', 'module', 'm02-what-the-module-does-not-have', 4, 'What does the remaining-life door return when it is handed a rate of zero?', '["An unbounded life with a passing verdict, since a line losing no metal meets any design life that could be asked of it.", "A refusal naming the rate, in the same shape as the refusal it raises for a negative rate and for a rate that is not a number.", "No life, no verdict, `unbounded` true, and a note telling the reader to find out why the rate is zero before reading it as a pass.", "A life of zero years and a failing verdict, because a rate the module cannot explain is treated as the most limiting case available."]'::jsonb, 2, '`remainingYears` is null and `meetsDesignLife` is null. The strongest reassurance on the screen would otherwise arrive from the weakest input, and the golden''s own zero-rate row records the same shape.'),
  ('corrosion', 'advanced', 'module', 'm02-what-the-module-does-not-have', 5, 'Four separate paths reach a rate of zero, and a reader should be able to list them. Which set is right?', '["A blank CO2 box, a blank temperature box, an oil-wet wetting regime, and a corrosion inhibitor at 100 percent efficiency and 100 percent availability.", "A pH below the reference, a blank velocity, a stream with no CO2 in it, and a corrosion inhibitor at 100 percent efficiency and 100 percent availability.", "A wall shear above the film-stripping threshold, an oil-wet wetting regime, a typed zero CO2 mole fraction, and a stream with no CO2 in it.", "An oil-wet wetting regime, a stream with no CO2 in it, a corrosion inhibitor at 100 percent efficiency and 100 percent availability, and a typed zero CO2 mole fraction."]'::jsonb, 3, 'The blank boxes and the pH below the reference are refusals rather than zero rates, and a shear above the threshold removes the corrosion inhibitor credit and raises the rate. A typed zero is a positive assertion and a blank box is a question the engine cannot answer.'),
  ('corrosion', 'advanced', 'module', 'm02-what-the-module-does-not-have', 6, 'Which course owns the erosional velocity criterion, and what does this engine have in its place?', '["The Pipeline Network course at its Associate tier. This engine has no erosional-velocity criterion and reads the wall shear against the same limit that course publishes.", "The Casing and Tubing Design course at its Expert tier. This engine has no erosional-velocity criterion at all and computes a wall shear for a different purpose.", "The Torque and Drag course at its Expert tier. This engine has no erosional-velocity criterion and uses the film risk word as a stand-in wherever one is needed.", "This module itself, through the film risk word, which is why the Casing and Tubing Design course cites this studio when a velocity limit is wanted."]'::jsonb, 1, 'The criterion is cited again in Nodal Analysis and in Gas Well Deliverability. The repair deliberately did not add one here, and the wall shear this module computes answers whether a corrosion inhibitor film survives.'),
  ('corrosion', 'advanced', 'module', 'm02-what-the-module-does-not-have', 7, 'The wall shear in this module carries a coloured risk word. What question does that pairing answer?', '["Whether the line is running above its erosional velocity, which is the reading the coloured word was added to the summary rail in order to give.", "Whether mechanical erosion is removing metal, which the module estimates from the shear once the film-stripping threshold of 100.000000000000 Pa is passed.", "Whether a corrosion inhibitor film survives on the steel. This engine has no erosional-velocity criterion, so a low risk word is not clearance on velocity.", "Whether the flow has reached the turbulent branch of this module''s friction factor, which is the switch the coloured word turns over at."]'::jsonb, 2, 'The shear meets two held thresholds, at 100.000000000000 Pa and 50.000000000000 Pa. Above the higher one the film is taken to be stripped and the corrosion inhibitor credit is removed from the rate, which is a verdict about a film. The Pipeline and Line Sizing course computes its own friction factor and its own Reynolds number on a different correlation with a different transition, so the two will not agree on the same pipe.'),
  ('corrosion', 'advanced', 'module', 'm02-what-the-module-does-not-have', 8, 'How much of mechanical erosion does this module model?', '["None of it. There is no sand rate, no particle size and no impingement angle here, and no erosional-velocity criterion either.", "The impingement part of it, through the wall shear, which is why the shear is reported beside the rate rather than folded into it.", "The solids part of it, once a sand rate is supplied, and the module falls back on the wall shear when no sand rate has been entered.", "All of it above the film-stripping threshold of 100.000000000000 Pa, which is where erosional wall loss is taken to begin in this engine."]'::jsonb, 0, 'Mechanical erosion means wall loss from entrained solids or from liquid impingement. The one rate this engine returns is a general uniform corrosion rate, and a line passing every check here may still be losing metal that way with nothing in the module able to say so.'),
  ('corrosion', 'advanced', 'module', 'm02-what-the-module-does-not-have', 9, 'How should this module''s friction factor and this module''s Reynolds number be read against the Pipeline and Line Sizing course?', '["As the same numbers reached twice. Both modules run the same correlation, so the two agree on any pipe and either one may be quoted as the platform''s answer.", "As a second set. This module has its own, on a two-branch form switching at Reynolds 4000.000000, and the line sizing course computes its own with a different correlation and a different transition.", "As a duplicate the repair removed. The line sizing course now owns both quantities and this module reads its friction factor across rather than forming one.", "As a layered pair. The line sizing course supplies the laminar branch and this module supplies the turbulent branch, which is what the Reynolds 4000.000000 switch selects between."]'::jsonb, 1, 'The two will not agree on the same pipe and the engine says so in its own docstring. Removing the duplicate is a cross-module decision the repair deliberately left alone, so this course names the seam rather than hiding it.'),
  ('corrosion', 'advanced', 'module', 'm02-what-the-module-does-not-have', 10, 'The engine returns one rate. What is a reader entitled to take from it about the worst spot on the line?', '["Nothing. It is a general uniform rate, and the engine names a localised-attack rate among the things it does not provide.", "A conservative bound, since a uniform rate is above the local rate wherever the film is intact.", "A pitting rate wherever the regime is sulphide, which is the branch the module carries for localised attack and reports through the withheld block.", "A weld and top-of-line rate, since the correlation is fitted on a general surface and the engine applies the wetting regime factor to cover the rest."]'::jsonb, 0, 'Uniform corrosion and localised attack fail a line in different ways and on different timescales, and a single rate has no geometry in it. The engine cannot warn a reader who takes it the other way, because it has no localised model to compare against.'),
  ('corrosion', 'advanced', 'module', 'm02-what-the-module-does-not-have', 11, 'The sour flag on a screening comes back true. What does that value commit the engine to?', '["That the stream needs a sour-service material, which the engine then names once the severity region has been resolved from the partial pressure.", "That sulphide stress cracking is expected at these conditions, which is the criterion the threshold was placed to separate in the first place.", "That the CO2 rate model has stopped describing the surface at these conditions.", "That the H2S partial pressure sits above a threshold whose own value the engine declares held in `thresholdHeld`."]'::jsonb, 3, 'The door compares one partial pressure against one threshold and reports the comparison in bar and in psia with the decades above it. A true flag does not mean the line will crack and a false one does not mean it will not.'),
  ('corrosion', 'advanced', 'module', 'm02-what-the-module-does-not-have', 12, 'Three studios on this platform use the phrase corrosion allowance. How do they differ?', '["All three add an allowance to a wall, and this studio is the only one of them that also reports what is left of it after a stated consumed depth.", "All three read the same allowance from a shared registry, which is what keeps a life computed here against a wall sized in one of the other two.", "This studio consumes an allowance to give a life, while the Pipeline and Line Sizing studio adds one to a pressure-containing wall and the Storage Tank studio adds one to a shell course.", "This studio and the Storage Tank studio both consume one, while the Pipeline and Line Sizing studio is the only one of the three that sizes a wall around it."]'::jsonb, 2, 'There is no link between them and no minimum thickness anywhere in this module, so the wall this studio is eating is not the wall either of the other two sized. That is recorded, it is stated in the studio''s help, and it is deliberately left unwired.'),
  ('corrosion', 'advanced', 'module', 'm02-what-the-module-does-not-have', 13, 'This module cannot say what the corrosion allowance is being taken off. Which course owns the calculation that would say?', '["The Pipeline Network course at its Associate tier, which owns the Barlow thin-wall relation with a design factor.", "The Torque and Drag course at its Expert tier, which owns wall loss taken to a derated burst pressure and therefore owns the wall the allowance sits on.", "The Well Integrity and Plug and Abandonment course, which owns the barrier envelope the allowance is measured inside on any line in service.", "The Casing and Tubing Design course at its Expert tier, which owns the erosional velocity criterion and the wall thickness that criterion is applied to."]'::jsonb, 0, 'This module has no minimum thickness, so it cannot say what the allowance is taken off. Wall loss to a derated burst pressure is a separate owner again, and this module consumes an allowance and never computes a pressure, so that comparison is a pivot rather than a derivation. This engine has no erosional-velocity criterion of its own either.'),
  ('corrosion', 'advanced', 'module', 'm02-what-the-module-does-not-have', 14, 'The Well Integrity and Plug and Abandonment course is the one live course that points at this one. What does it say, and what follows?', '["It states that its barrier envelope already carries a corrosion allowance, so this course computes the life of that envelope and reports it back into the barrier logic.", "It states that it owns wall loss on abandoned wells only, so this course covers lines in service and the two split the same calculation between them.", "It states that it cites this module for a remaining life, so the barrier verdict there is reached from the allowance arithmetic computed here.", "It states in its own scope that it carries no corrosion model, no wall loss and no remaining life, and this course fills exactly that refusal."]'::jsonb, 3, 'A barrier envelope is a different object from a corrosion allowance and neither term substitutes for the other. A lesson here may name that course as the owner of barrier logic and must not borrow its vocabulary.'),
  ('corrosion', 'advanced', 'module', 'm02-what-the-module-does-not-have', 15, 'On one of the digest''s teaching streams the allowance is 3.175000 mm with 0.400000 mm consumed, the rate is 1.676428 mm/yr, the remaining life is 1.655305 yr and the required allowance is 33.528563 mm. What do those four numbers rest on?', '["The pin table alone, since a remaining life is itself one of the thirty constants the digest measures out of the engine and pins against a literal.", "A minimum thickness the module computes from the allowance, which is what makes the required allowance of 33.528563 mm a statement about a real wall.", "A division and a multiplication over a typed allowance, a typed consumed depth and the correlation''s rate, and none of them knows the wall thickness or the pipe grade.", "The Barlow relation, which this module applies with a default design factor so that the allowance can be checked against the wall it is taken off."]'::jsonb, 2, 'The arithmetic inside the door is exact, and the rate it divides by inherits whatever the correlation rests on. On another stream the same allowance at 0.076842 mm/yr gives 36.112878 yr, a required allowance of 1.536848 mm and a shortfall of 0.000000 mm.'),
  ('corrosion', 'advanced', 'module', 'm03-the-label-and-the-band', 1, 'What is the whole contract of the category door?', '["A rate and the conditions that produced it go in, so the word can be softened wherever the wetting regime or the sour comparison says the rate is an upper bound.", "A rate and the remaining life go in together, which is what lets the word separate a fast rate on a thick wall from a slow one on a thin wall.", "A rate in millimetres a year goes in and one word comes out. It carries no conditions, no stream, no allowance and no life.", "A whole screening goes in and the word comes back on it."]'::jsonb, 2, 'The door sees nothing but the rate. It does not know the temperature, the CO2 fugacity, the velocity, the corrosion allowance or the corrosion inhibitor programme, and it performs three comparisons against the band edges and one against zero, and stops.'),
  ('corrosion', 'advanced', 'module', 'm03-the-label-and-the-band', 2, 'How many band words does the door return, how many edges separate them, and what is the extra word?', '["Four band words with three edges between them, plus one more word that is no band at all and is returned at exactly zero and below.", "Five band words with four edges between them, the fifth band being the one the door reaches whenever the rate it is handed is small enough to sit under the lowest edge.", "Four band words with four edges between them, the fourth edge being the upper limit above which the door stops labelling and returns null instead of a word.", "Three band words with three edges between them, since the highest edge is open ended and the word above it is the same word the door returns at the edge itself."]'::jsonb, 0, 'The four bands are low, moderate, high and severe. The extra word is negligible and it is what the door returns at zero and below rather than a band it reaches by being small.'),
  ('corrosion', 'advanced', 'module', 'm03-the-label-and-the-band', 3, 'The digest names a fourth boundary in this door. Where is it?', '["At 4.200000 mm/yr, where the golden''s highest category row sits and the severe band is taken to run out of meaning altogether.", "At 0.000000001 mm/yr, which is the smallest positive rate the golden carries and the value the door first stops calling a rate negligible at.", "There is no fourth boundary. Three edges separate four words, and the extra word is reached by the rate being small rather than by crossing anything.", "At zero itself, which the golden pins from both sides."]'::jsonb, 3, 'At exactly 0.000000 mm/yr the word is negligible and at 0.000000001 mm/yr it is already low. The test the engine applies is whether the rate is greater than zero, so no rate comes back negligible for being small.'),
  ('corrosion', 'advanced', 'module', 'm03-the-label-and-the-band', 4, 'One row of the golden''s category table is printed past six decimals while every other row is printed at six. Why?', '["It is the only row where the golden and the engine disagree, so the extra digits are there to show the size of the gap between the two of them.", "At six decimals it would read 0.000000 and a reader would see the row above it twice.", "It sits on an edge, and every row on an edge is printed at the precision the edge is measured to so that the comparison can be checked by hand.", "It is the row the vendored jest suite pins, and a pin is printed at the full precision of the double rather than at the digest''s own precision."]'::jsonb, 1, 'It is the smallest positive rate the golden carries, and it is one of the two rows that pin the zero boundary. The row above it is the rate of exactly zero.'),
  ('corrosion', 'advanced', 'module', 'm03-the-label-and-the-band', 5, 'Each of the three edges between the bands is applied in one direction. Which, and how is it pinned?', '["Strictly above: a rate sitting exactly on an edge stays in the band below it, which is why the golden carries a row a ten-thousandth under each of the three.", "It varies by edge: the lowest is at or above and the two higher ones strictly above.", "At or above: a rate sitting exactly on an edge takes the band above it, and the golden carries rows on both sides of all three edges.", "It is undefined, because the door compares against the edges with a tolerance."]'::jsonb, 2, 'The golden carries 12 category rows, both sides of all three edges, and the engine agrees with every one of them. The edges themselves are measured by bisecting the word the door returns.'),
  ('corrosion', 'advanced', 'module', 'm03-the-label-and-the-band', 6, 'A blank rate, a rate that is not a number and a negative rate go to the category door. Which of the three behaves differently from the other two, and why does it matter?', '["The blank rate. It refuses with a message naming the input, while a negative rate and a rate that is not a number both come back as null from the same branch.", "The rate that is not a number. It returns the same word as a negative rate does.", "None of them. All three return null, which is the door declining to label.", "The negative rate. The other two return null, while a negative rate gets an answer, and it is the most reassuring word the door has."]'::jsonb, 3, 'A blank rate and a rate that is not a number both return null, which is the door declining. The negative rate is answered instead, and that is a function answering where it could decline with the least alarming word available. Nothing upstream in the screening door hands it one.'),
  ('corrosion', 'advanced', 'module', 'm03-the-label-and-the-band', 7, 'What is `categoryHeld` and what does it do?', '["A field returned beside the category, declaring that the band edges carry no source. It is true at the shipped defaults.", "A field returned when the band edges have been overridden by a caller, so a reader can tell a default label from one produced under a tightened set of edges.", "A flag raised when the rate the door was handed is itself an upper bound, which is how the sulphide and mixed regimes mark the word they produce.", "A flag raised when the door declines to label a rate at all."]'::jsonb, 0, 'A field that declares its own band unsourced is stronger engineering than a footnote in a help page, because a caller can read it, print it and act on it. The studio prints it behind a disclosure alongside the rest of the held list.'),
  ('corrosion', 'advanced', 'module', 'm03-the-label-and-the-band', 8, 'The engine''s own held list says something unusual about the category bands. What does it say?', '["That they were taken from a published rate-band table whose clause number the golden records.", "That they carry no source and may be optimistic by one or two steps against the bands commonly cited for carbon steel in production service.", "That they are conservative by one or two steps, so a word here reads worse than it would elsewhere.", "That they are correct for carbon steel and unsourced for every other metallurgy."]'::jsonb, 1, 'The bands are the ninth of the eleven held items. No corrosion rate-band table exists anywhere in this repository, which is also why the golden is synthetic and says so.'),
  ('corrosion', 'advanced', 'module', 'm03-the-label-and-the-band', 9, 'The held list says the bands may be optimistic by one or two steps. What is stated there and what is missing?', '["Both the direction and the size are stated, so a reader can shift a word by two bands and quote the held list as the authority for having done it.", "The size is stated and the direction is not, so a reader knows how far the edges could move and has no way to tell which way they would move.", "Neither is stated. The sentence records only that the numbers are unsourced, and one or two steps describes how many edges exist rather than an error.", "The direction is stated. The size beyond one or two steps is not, and the phrase commonly cited names no document a reader could go and check."]'::jsonb, 3, 'A direction without a magnitude and without a citation is a warning a reader can carry into a conversation. It is not a correction and nobody can apply it to a number on a screen, which is why it sits on the held list rather than in a help page as guidance.'),
  ('corrosion', 'advanced', 'module', 'm03-the-label-and-the-band', 10, 'Why would tightening the three edges so the words read more conservatively not repair them?', '["It would break the twelve golden category rows, which pin the edges from both sides, and the golden cannot be recut while the engine stays vendored.", "It would move every rate with them, since the rate is formed by the same comparisons.", "It would replace one unsourced set of numbers with a different unsourced set, and it would do it under the appearance of a fix.", "It would contradict the engine''s own admission about the direction of the error."]'::jsonb, 2, 'The screen would then carry numbers nobody could source with a claim of correctness attached that the first set never had. The H2S screening threshold of 0.003500000000 bar was kept for the same reason, declared held in a field and printed in both units.'),
  ('corrosion', 'advanced', 'module', 'm03-the-label-and-the-band', 11, 'Move the first band edge to a smaller number and rerun the teaching streams. What moves?', '["The word and the remaining life together, because the life is computed from the band the rate lands in and a stream that changes word changes life with it.", "The word on any stream between the old edge and the new one. No rate moves, no remaining life moves and no binding constraint moves.", "The word and the binding constraint together, because the allowance step reads the band first.", "The word and the rate together, because the wetting factor is selected from the category."]'::jsonb, 1, 'The arithmetic of the module is untouched and the screen reads differently everywhere. Moving a held correlation constant is the other experiment: every rate moves, every life moves, and the words move with them.'),
  ('corrosion', 'advanced', 'module', 'm03-the-label-and-the-band', 12, 'Why does a reader who treats the word as a summary of the rate get into trouble?', '["The two layers fail independently. The word inherits everything uncertain in the rate and then adds a second unsourced layer of its own.", "The word is computed before the rate, so a rate that changes after the label has been chosen leaves the screen carrying a word from an earlier pass.", "The word is the more reliable of the two, since three comparisons carry less uncertainty.", "The word is derived from the conditions rather than from the rate itself."]'::jsonb, 0, 'The rate is the output of a correlation over stream conditions and the word is the output of three comparisons against three constants and one against zero. Keeping them apart is the whole of this module.'),
  ('corrosion', 'advanced', 'module', 'm03-the-label-and-the-band', 13, 'The shipped default case screens at 0.754524 mm/yr and the studio prints a word beside it. What does that one row show about the screen?', '["That the correlation and the bands were fitted together, so the layers can be checked here.", "That the word is the safer figure to quote, since a band absorbs the uncertainty in the rate.", "That two unsourced layers are stacked in it. The rate is built on held constants and the word is three more comparisons laid on top of the rate.", "That the screen is internally consistent, which the twelve golden rows establish."]'::jsonb, 2, 'A band set one step tighter would call the same number something worse and nothing in this repository says which band set is right. The screen prints the rate and the word in the same typeface, and telling the two apart is the skill this tier is for.'),
  ('corrosion', 'advanced', 'module', 'm03-the-label-and-the-band', 14, 'Not everything on that same default screen is layered that way. Which figures on it are exact arithmetic over what the user typed?', '["The remaining life of 4.207953 yr and the shortfall of 11.915473 mm, since both come out of a door that performs one division over numbers the caller supplied.", "The wall shear of 14.408065 Pa and this module''s Reynolds number of 416686.8569, since a shear follows from a momentum balance over quantities the user entered.", "The computed film onset of 80.984504 C and the pH factor of 0.562341, since both are reached from the typed conditions without a band edge anywhere in the chain.", "The H2S partial pressure of 0.051000 bar, its 0.739699 psia, and the effective corrosion inhibition of 85.500000 percent."]'::jsonb, 3, 'The partial pressure is the total pressure times the mole fraction, the psia value is a unit conversion by the engine''s bar to psia factor, and the effective figure is arithmetic over two typed percentages. The remaining life is a division that rests on a rate, so it inherits what the rate inherits. The Pipeline and Line Sizing course computes its own friction factor and its own Reynolds number on a different correlation with a different transition, so the two will not agree on the same pipe.'),
  ('corrosion', 'advanced', 'module', 'm03-the-label-and-the-band', 15, 'A decision turns on the difference between two adjacent band words. What is the right reading?', '["The module cannot support it, because that difference is exactly the width of the uncertainty the engine admits to in its own held list.", "The module supports it as far as the edge, since the golden pins the edges from both sides.", "The module supports it wherever `categoryHeld` is false, which is the flag a caller reads first.", "The module supports it in the direction the held list names, since the admission fixes the sign."]'::jsonb, 0, 'Treat the word as a rough sort of a list of streams. When the argument rather than the sorting is wanted, take the rate, the conditions that produced it and the held items in its chain to whoever owns the decision.'),
  ('corrosion', 'advanced', 'module', 'm04-the-summary-that-was-missing', 1, 'A screening returns seven independent numbers and reconciles none of them. What does a reader do with that, and why?', '["They read the numbers in the order the screen prints them and act on the first one that carries a threshold, which is the order the engine computes them in.", "They summarise it by reading the largest number, because nothing on an unreconciled screen ranks its own contents and attention follows the units.", "They discard the screening and rerun it, because seven unreconciled numbers means it came back incomplete.", "They average the alarming figures against the comfortable ones and act on the middle."]'::jsonb, 1, 'A wall shear of 370 Pa looks worse than a life of 0.161915 yr, and on that stream the life is the consequence and the shear is the cause. That is a property of the units rather than of the engineering.'),
  ('corrosion', 'advanced', 'module', 'm04-the-summary-that-was-missing', 2, 'Across the six teaching streams the binding constraint takes four different values. What are they?', '["Mass transfer to the wall, reaction kinetics, the corrosion allowance against the design life, and the rate category band the stream lands in.", "Wall shear on the corrosion inhibitor film, the sour threshold comparison, the corrosion allowance against the design life, and mass transfer to the wall.", "The model does not apply, the erosional velocity limit, wall shear on the corrosion inhibitor film, and the corrosion allowance against the design life.", "Mass transfer to the wall, the corrosion allowance against the design life, the model does not apply, and wall shear on the corrosion inhibitor film."]'::jsonb, 3, 'Four constraints across six streams is what makes it a summary. A summary that always said the same thing would be a heading, and there is no erosional velocity limit anywhere in this engine to bind on.'),
  ('corrosion', 'advanced', 'module', 'm04-the-summary-that-was-missing', 3, 'The binding constraint is chosen by walking a fixed sequence and stopping at the first question that fires. What is the sequence?', '["Does the model apply at all, is the film being stripped, does the allowance fail the design life, are the two resistances comparable, is transport controlling, otherwise kinetics.", "Is the film being stripped, does the model apply at all, is transport controlling, are the two resistances comparable, does the allowance fail the design life, otherwise kinetics.", "Does the allowance fail the design life, does the model apply at all, is the film being stripped, is transport controlling, are the two resistances comparable, otherwise kinetics.", "Is transport controlling, are the two resistances comparable, is the film being stripped, does the model apply at all, does the allowance fail the design life, otherwise kinetics."]'::jsonb, 0, 'The sequence is the engineering content of the summary. Change the order and the same stream gets a different headline out of the same numbers, so the order is a claim about what matters first.'),
  ('corrosion', 'advanced', 'module', 'm04-the-summary-that-was-missing', 4, 'A stream is reported as mass transfer controlled. What has the sequence already established about it before it reaches that step?', '["That its rate is the largest number on the screen, which is what the steps above the transport test are there to confirm before transport is named.", "That it has passed the film test and nothing else.", "That the CO2 rate model applies, that the corrosion inhibitor film survives the shear, and that the allowance meets the design life.", "That its two resistances are comparable within the reporting margin."]'::jsonb, 2, 'A lower step is reached only because every step above it is satisfied. The comparable step sits above the transport test and is reached first, so a stream named transport controlled has already passed it rather than satisfied it.'),
  ('corrosion', 'advanced', 'module', 'm04-the-summary-that-was-missing', 5, 'Why does applicability sit at the top of the sequence rather than anywhere else in it?', '["Because it is the step that fires on the most streams, and a sequence that stops at the first firing question should try its commonest answer first of all.", "Because the applicability test needs only the mole fractions, so it can be answered before the shear and the rate have been computed at all on that stream.", "Because the withheld block has to be built before the category and the life are issued, and the applicability step is where that block is assembled.", "Any lower limit would be ranked inside a model that had already stopped describing the stream."]'::jsonb, 3, 'One teaching stream fails it: the H2S to CO2 ratio puts it in the sulphide regime and the binding constraint comes back with no value attached. A film stripping verdict on a surface the correlation does not cover is a precise answer to the wrong question.'),
  ('corrosion', 'advanced', 'module', 'm04-the-summary-that-was-missing', 6, 'Why does the film stripping test sit above the allowance test rather than below it?', '["The shear is the larger number on most screens, and a sequence that ranks limits has to meet the larger of two candidates before it can meet the smaller one.", "The rate depends on the shear verdict, because a stripped film removes the corrosion inhibitor credit before the rate is formed, so a life computed without it is a life at the wrong rate.", "The allowance test needs a design life and the shear test does not, so the shear test is placed where it can run on a screening that carries no design life at all.", "The film-stripping threshold of 100.000000000000 Pa is pinned and the design life is typed in, so the pinned comparison is applied before the typed one is reached."]'::jsonb, 1, 'One teaching stream binds at 370 Pa against the 100 Pa at which this module takes the film to be stripped. Both thresholds are held, so the order argument stands on the structure of the calculation rather than on the value of either number.'),
  ('corrosion', 'advanced', 'module', 'm04-the-summary-that-was-missing', 7, 'Each binding constraint is returned with the value it turns on. What does the allowance constraint carry on the two streams that bind there?', '["The rate and the design life, at 1.676428 mm/yr against 20 yr and 0.361255 mm/yr against 20 yr, since the constraint names the two inputs that produced it.", "The required allowance on each, at 33.528563 mm and 7.225094 mm, since the constraint is about an allowance and the required figure is the allowance it asks for.", "1.7 yr of 20 yr, short by 30.75 mm of allowance, and 7.7 yr of 20 yr, short by 4.45 mm.", "The consumed depth against the allowance, at 0.400000 mm of 3.175000 mm on both, since the constraint turns on how much of the wall has already gone."]'::jsonb, 2, 'The constraint names the limit and shows the value it turns on so that the claim can be checked rather than taken. Every one of those values is derived from something the screening had already computed.'),
  ('corrosion', 'advanced', 'module', 'm04-the-summary-that-was-missing', 8, 'Where did the constraints come from, and what entered the module with them?', '["Each is derived from something already computed, and no new correlation and no new constant entered the module with the summary.", "Each is derived from the held list, and the eleven items were extended to cover the four constraint types so the summary could declare its own sources.", "Each rests on a small fitted weighting that ranks the limits against one another.", "Each is computed afresh from the stream conditions on every screening."]'::jsonb, 0, 'The shear comparison uses the shear and the threshold the engine already has, the allowance test uses the life and the design life already returned, and the transport test compares two terms the rate already carries. A summary layer with a fitted number of its own would be another held item hiding behind a sentence.'),
  ('corrosion', 'advanced', 'module', 'm04-the-summary-that-was-missing', 9, 'Both thresholds in the film stripping comparison are held. What does that do to the argument for the order of the sequence?', '["It weakens it to a convention, since a step whose comparison rests on two unsourced numbers cannot be defended as sitting above a step that rests on typed ones.", "It removes the step, which is why the engine reports the shear beside the rate rather than ranking it.", "It moves the step below the allowance test, since a typed comparison outranks a held one.", "Nothing. The order rests on the structure of the calculation, because the rate is formed after the shear verdict whatever the threshold is set to."]'::jsonb, 3, 'The threshold values are held and the coupling between them is not. A verdict taken on an unsourced threshold still changes which rate is formed, so a life computed without it is a life at the wrong rate.'),
  ('corrosion', 'advanced', 'module', 'm04-the-summary-that-was-missing', 10, 'The shipped default case binds on the corrosion allowance against the design life at 4.2 yr of 20 yr. What happens to the constraint under the four changes the digest sweeps?', '["At 60 ft per second it binds on mass transfer to the wall, and at 1 mol percent H2S and oil wet it binds on wall shear on the corrosion inhibitor film.", "At 60 ft per second it binds on wall shear at 362 Pa, at 1 mol percent H2S on the allowance against the design life, and oil wet on the model not applying.", "At 60 ft per second it binds on wall shear at 362 Pa, and at 1 mol percent H2S and oil wet it binds on the model not applying.", "At 60 ft per second and at pH 4.0 it binds on wall shear."]'::jsonb, 2, 'The last two are the same constraint reached by different roads, and in both the reader''s next action is to read the withheld block rather than to act on a number. The pH change leaves the constraint on the allowance against the design life.'),
  ('corrosion', 'advanced', 'module', 'm04-the-summary-that-was-missing', 11, 'A stream binds on mass transfer to the wall. What does the engine say follows from that?', '["That velocity and line size move this rate and the chemistry does not.", "That the corrosion inhibitor programme is what moves this rate, since the transport term is the one the credit is applied to before the series combination.", "That the rate is an upper bound, since a transport limited surface is one the CO2 correlation is describing at the edge of where it was fitted.", "That the reaction term can be ignored, since the series combination sits at whichever term is smaller and the larger one has dropped out of the answer."]'::jsonb, 0, 'On one teaching stream the transport term is 2.34 mm/yr against a reaction term of 27.66 mm/yr, and on another 0.09 mm/yr against 10.01 mm/yr. Changing the temperature or the carbon dioxide on a transport controlled stream moves the larger term and the answer barely follows.'),
  ('corrosion', 'advanced', 'module', 'm04-the-summary-that-was-missing', 12, 'The engine says that slowing the line changes this answer before anything else does. What kind of statement is that?', '["A recommendation, which is why the binding constraint is the one field on the screening that the studio renders as an action for the reader to take.", "A statement about the sensitivity of the module''s own output. It describes which limit governs the number and stops there.", "A statement about the world, reached by setting the shear against the erosional velocity limit that the wall shear is compared with on every screening.", "A refusal, in the same family as the withheld block."]'::jsonb, 1, 'Naming a limit is a statement about the calculation and recommending an action is a statement about the world, and the second needs a standard, a cost, an operating context and a consequence. This engine has no erosional-velocity criterion, so no constraint here is ever a velocity limit. The sentences are written in plain English and plain English sounds like guidance.'),
  ('corrosion', 'advanced', 'module', 'm04-the-summary-that-was-missing', 13, 'A stream binds on wall shear on the corrosion inhibitor film. What does that constraint still not know?', '["Whether the shear was computed on the turbulent branch, which the constraint cannot report because the branch name is held along with the Reynolds 4000.000000 switch.", "Whether the corrosion inhibitor credit was removed, which is reported in a separate field because the constraint names the limit without naming its consequence.", "Whether the velocity is erosional, because this engine has no erosional-velocity criterion and computes a wall shear to decide whether a film survives.", "Whether the rate is an upper bound, which the regime door settles separately and the binding constraint has no access to at the point it is chosen."]'::jsonb, 2, 'Read the four constraint types against the not-provided list and the gaps are plain. A stream binding on the allowance has no retirement thickness and no inspection interval beside it, and a stream binding on the model not applying has no cracking criterion of any kind.'),
  ('corrosion', 'advanced', 'module', 'm04-the-summary-that-was-missing', 14, 'Why is four different constraints across six streams the point rather than an accident of the sample?', '["A summary that always said the same thing would be a heading rather than a summary.", "Because six streams is the smallest sample that reaches every branch, which is why the vendored golden carries exactly six whole screenings to pin the summary.", "Because the four constraints are equally likely by construction, so a spread over six streams is what shows the ranking has not settled on one branch.", "Because a constraint that fired on every stream would be the one held item in the summary layer, and the spread is what proves no fitted number entered it."]'::jsonb, 0, 'Each of the four implies a different first move: the line speed, a specification decision, velocity and line size, or reading the withheld block because no rate verdict is being offered.'),
  ('corrosion', 'advanced', 'module', 'm04-the-summary-that-was-missing', 15, 'One step of the sequence asks whether the two resistances are comparable. What is the margin that step uses, and what does it claim?', '["Within 10.000000 percent the engine names the larger of the two terms, since a bare comparison of two nearly equal numbers should resolve towards the safer reading.", "Within 0.100000 percentage points the engine answers comparable, which is the same trigger the corrosion inhibitor shortfall warning is measured to fire at.", "Within one rate category band the engine answers comparable, which ties the reporting margin to the bands and is why the margin is held along with them.", "Within 10.000000 percent the engine answers comparable rather than naming a term. It is a reporting threshold and no claim about where mass transfer stops mattering."]'::jsonb, 3, 'A bare comparison of two nearly equal numbers flips on floating-point noise, so the margin exists to stop the word flipping. The measured margin is 0.100000 as a ratio and the engine says in its own words that it is a reporting threshold.'),
  ('corrosion', 'advanced', 'module', 'm05-inversion-against-a-limit', 1, 'What is `requiredAllowanceMm`, exactly?', '["The rate times the design life less whatever has already been consumed, which is the allowance the line still has to find before it meets its design life.", "The remaining allowance divided by the design life, which is what a year of service takes.", "The rate times the design life, which is the allowance a new line would need. It does not know the allowance the line has or what has been consumed.", "The allowance that makes `meetsDesignLife` turn true, found inside the door."]'::jsonb, 2, 'It is a property of the rate and the design life alone. On the worked case at a stated 0.250000 mm/yr with a 20 year design life it is 5.000000 mm, whatever the allowance and the consumed depth happen to be.'),
  ('corrosion', 'advanced', 'module', 'm05-inversion-against-a-limit', 2, 'A line has a 4 mm allowance with 1.2 mm gone, a 20 year design life and a stated rate of 0.250000 mm/yr. What allowance reinstates the design life?', '["6.200000 mm, found by bisecting the total allowance until `meetsDesignLife` turns true.", "5.000000 mm, which is `requiredAllowanceMm` on this case and is the allowance the door names when it is asked what the design life demands.", "2.200000 mm, which is the shortfall on this case and is the amount the allowance falls short of what the design life asks of it.", "2.800000 mm, which is the remaining allowance on this case and is what the line still has available to lose over the years ahead of it."]'::jsonb, 0, 'Three quantities sit side by side here and only one of them reinstates the design life. `requiredAllowanceMm` is 5.000000 mm, the remaining allowance is 2.800000 mm and the shortfall is 2.200000 mm.'),
  ('corrosion', 'advanced', 'module', 'm05-inversion-against-a-limit', 3, 'On that same case `requiredAllowanceMm` is 5.000000 mm and the reinstating allowance is 6.200000 mm. Why is the gap exactly 1.2 mm?', '["Because the shortfall of 2.200000 mm is split between the two figures, and the part of it the remaining allowance already covers is the difference between them.", "Because the bisection converges from above and stops one step short, so the gap is the width of the last bracket rather than a quantity with a meaning.", "Because the rate of 0.250000 mm/yr is applied over the design life twice.", "The required figure measures a new line and the reinstating figure measures this one, so they differ by what has already been consumed."]'::jsonb, 3, 'The digest asserts that identity on every rebuild rather than quoting it. The shortfall of 2.200000 mm is a third quantity again, because it compares the required allowance against what is left rather than against the allowance the line started with.'),
  ('corrosion', 'advanced', 'module', 'm05-inversion-against-a-limit', 4, 'Why bisect the engine''s own verdict rather than rearrange the arithmetic on paper?', '["The arithmetic inside the door is not a division, so a rearrangement cannot be formed at all and the bisection is the only route the field admits.", "The bisection meets every guard, rounding and branch inside the door, while a rearrangement answers a question you wrote down and agrees only while the door behaves as you assumed.", "The bisection reaches the answer in fewer engine calls, which matters because the remaining-life door is the slowest of the fourteen in this module.", "The rearrangement uses held constants and the bisection does not, so only the bisection keeps the correlation''s unsourced numbers out of the answer."]'::jsonb, 1, 'A zero rate returns null years, a null verdict and `unbounded` true. An allowance consumed past its own depth refuses. A design life left out gives a life with a null verdict. None of that falls out of dividing one number by another.'),
  ('corrosion', 'advanced', 'module', 'm05-inversion-against-a-limit', 5, 'The design life is left out of a remaining-life call on a case that would otherwise give 13.333333 yr. What comes back?', '["A refusal, because the door needs a design life before it can form either the required allowance or the verdict it reports beside the years.", "13.333333 yr with `meetsDesignLife` true, since a line with no stated design life meets every life that could be asked of it and passes by default.", "13.333333 yr with `requiredAllowanceMm` at 0.000000 mm and a shortfall of 0.000000 mm, since a design life of nothing demands an allowance of nothing.", "13.333333 yr with `meetsDesignLife` null, `requiredAllowanceMm` null and a shortfall of 0.000000."]'::jsonb, 3, 'A design life is optional and its absence is not a zero. That single sweep also separates the two allowance fields: the required figure is the one that goes null, and the years still arrive.'),
  ('corrosion', 'advanced', 'module', 'm05-inversion-against-a-limit', 6, 'A programme manager wants a stated effective protection at the efficiency already bought. How is the availability found?', '["Divide the target effective protection by the efficiency, since the effective figure is the product of the two and the division inverts it exactly.", "Bracket the efficiency instead and read the availability off the shortfall.", "Hold the efficiency, bracket the availability, and narrow the bracket until the effective figure the engine returns first reaches the target.", "Raise the efficiency until the target is met, since availability cannot be typed in."]'::jsonb, 2, 'Bisecting keeps every clamp in the loop. The engine clamps an efficiency below zero up to zero, one above a hundred down to a hundred, and an availability above a hundred the same way, and it names each clamp it applied in a field.'),
  ('corrosion', 'advanced', 'module', 'm05-inversion-against-a-limit', 7, 'A corrosion inhibitor with a datasheet efficiency of 95 percent runs at 80 percent availability. What does the programme deliver?', '["95.000000 percent effective protection for the 80 percent of the time it is present, which the engine reports beside an availability warning naming the gap.", "76.000000 percent effective protection, which is 19.000000 percentage points short of the datasheet figure and 4.800000 times the metal loss.", "80.000000 percent effective protection, since availability is the lower of the two.", "90.250000 percent effective protection, since the shortfall grows with the square of the availability."]'::jsonb, 1, 'The uninhibited rate applies for the fraction of the time the programme is off, and it is that time average that eats the wall. Availability is what limits the result and efficiency does not.'),
  ('corrosion', 'advanced', 'module', 'm05-inversion-against-a-limit', 8, 'A typed efficiency of 100 percent is used at 95 percent availability. What does the engine return, and what does it say about it?', '["95.000000 percent effective protection with no clamp and no hidden ceiling, and a note saying that this is the arithmetic of the number typed in.", "100.000000 percent effective protection, with a clamp recorded in the clamps field because no programme removes all metal loss while it is running.", "A refusal, because an efficiency of 100 percent would give a rate of zero and the module declines to issue an unbounded life off a typed percentage.", "95.000000 percent effective protection with the efficiency clamped from 100 down to the highest value the engine will credit on a filming amine."]'::jsonb, 0, 'A typed 100 percent gives exactly the availability. The note the engine adds says what that arithmetic is, and it is the shape to watch for wherever a typed number is carried straight through into an answer.'),
  ('corrosion', 'advanced', 'module', 'm05-inversion-against-a-limit', 9, 'The engine fires a warning on the corrosion inhibitor shortfall. Where is the trigger, and is it present on the shipped default case?', '["At 10.000000 percentage points of shortfall, and the shipped case is at 4.500000 percentage points, so the warning is absent on the first screen a user meets.", "At an efficiency strictly above 90 percent, and the shipped case is at exactly 90 percent efficiency, so the warning is silent on the first screen a user meets.", "At 0.100000 percentage points of shortfall, and the shipped case is at 4.500000 percentage points, so the warning is present.", "At 0.100000 percentage points of shortfall, with the shipped case at 0.000000."]'::jsonb, 2, 'The trigger is measured by bisecting the availability at which the warning first appears. At the shipped 90 percent efficiency and 95 percent availability the effective protection is 85.500000 percent.'),
  ('corrosion', 'advanced', 'module', 'm05-inversion-against-a-limit', 10, 'Two of the graded quantities in this course are ratios of engine rates rather than pure arithmetic over typed percentages. Why are they still clear of every held constant?', '["The ratio is taken after the pH correction and the scale factor are applied, and those are the only two places in the chain a held constant enters.", "The rates are computed at conditions the pin table covers, so the held constants in them are measured rather than declared and a measured constant is not held.", "The ratio is rounded to six decimals before it is graded.", "The two rates share the whole correlation chain, so it divides out exactly and only the corrosion inhibitor arithmetic is left in the ratio."]'::jsonb, 3, 'The shipped case gives a rate of 0.754524 mm/yr against an uninhibited 5.203611 mm/yr on the same conditions. The capstone generator measures the invariance rather than claiming it, by re-running at conditions that move the rate by more than half and cross the fugacity cap.'),
  ('corrosion', 'advanced', 'module', 'm05-inversion-against-a-limit', 11, 'This module''s Reynolds number is a graded quantity while the wall shear is not. What separates them?', '["The Reynolds number is a definition over four supplied properties, and the Blasius pair and the branch switch act on the friction factor downstream of it.", "The Reynolds number is exported and the wall shear is not, and a quantity the engine exports by name has been declared in a way the pin table can carry.", "The Reynolds number is dimensionless and the wall shear is not, so only the Reynolds number is free of the unit conversions the studio layer applies.", "The Reynolds number is pinned in the digest and the wall shear is bisected out of the risk word, and only a pinned quantity can be graded in this course."]'::jsonb, 0, 'Density times velocity times diameter over viscosity is a definition, and no graded field in this course reads a friction factor or a shear stress. The Pipeline and Line Sizing course computes its own Reynolds number with a different correlation and a different transition, so the two will not agree on the same pipe.'),
  ('corrosion', 'advanced', 'module', 'm05-inversion-against-a-limit', 12, 'One held item is a question about where the protective scale factor belongs. How is it kept out of every graded capstone answer?', '["The graded fields are all taken before the scale factor is applied, since the factor is the last multiplication in the chain and the capstone reads the earlier values.", "Every capstone scenario sits below its own computed film onset, so the factor is exactly one and multiplying by one in either place gives the same double.", "The capstone states the factor from an inspection survey in the way it states a rate.", "The capstone grades the factor as a ratio against the same case with it removed."]'::jsonb, 1, 'The capstone generator asserts the condition rather than assuming it. Nothing downstream of that factor is graded anywhere in this course, and five of the six digest streams also have a factor of exactly one.'),
  ('corrosion', 'advanced', 'module', 'm05-inversion-against-a-limit', 13, 'The studio converts a psig pressure by dividing by 14.5038 and the engine exports 14.503773800722. What does the difference cost, and what was done about it?', '["Nothing measurable, since the two agree well inside six significant figures, and the capstones state their conditions in field units as the studio does.", "A whole rate category step at the shipped defaults, which is why the conditions are stated in the engine''s units and the category is never graded here.", "The difference is the reason the fugacity pressure cap is held, since a pressure converted two ways can land on either side of 250.000000000000 bar.", "The shipped defaults give 0.754523654262 mm/yr through the studio''s divisor and 0.754524736514 mm/yr through the engine''s factor, so graded conditions are stated in the engine''s units."]'::jsonb, 3, 'The gap is far below anything a screening decision turns on and far above zero, which is exactly the size that fails a tolerance while mattering to nobody. Grading through the studio''s rounding would measure the app rather than the corrosion.'),
  ('corrosion', 'advanced', 'module', 'm05-inversion-against-a-limit', 14, 'A capstone in this course needs a rate for its allowance arithmetic. Where does that rate come from, and why?', '["From the correlation at the stated conditions, with the held constants declared beside it so a learner can see what the answer is resting on.", "From the uninhibited rate the engine returns, since that figure is free of the corrosion inhibitor arithmetic and therefore free of the two typed percentages.", "From an operator''s inspection survey, stated on the page, so that no held correlation constant enters any graded chain.", "From the category band the stream lands in, taken at the band edge, since an edge is a pinned number and a pinned number can be graded."]'::jsonb, 2, 'The remaining-life door takes an allowance, a consumed depth, a design life and a rate. With the rate stated, the whole arithmetic reduces to a division, a multiplication and a comparison over quantities somebody measured or typed.'),
  ('corrosion', 'advanced', 'module', 'm05-inversion-against-a-limit', 15, 'You want to know which of `requiredAllowanceMm` and the shortfall depends on the consumed depth. What is the one sweep that settles it?', '["Set the consumed depth to zero and rerun. The required allowance stays exactly where it was and the shortfall changes on any case that was short.", "Set the rate to zero and rerun. The required allowance goes to zero and the shortfall holds, which shows the shortfall is the field that carries the consumed depth.", "Set the allowance to zero and rerun. The door refuses, and the message names which of the two fields it was unable to form from the inputs it was given.", "Read the field names and the comment above the door, which states which inputs each field is formed from and is the quickest route to the same answer."]'::jsonb, 0, 'Read what a function returns rather than what its name suggests it returns, and find out by moving an input. On one teaching stream the shortfall is 0.000000 mm because the remaining allowance covers the required figure, and that zero is a pass on that one comparison and silent about everything else.'),
  ('corrosion', 'advanced', 'module', 'm06-what-this-engine-used-to-do', 1, 'Before the repair this engine computed a sour-service severity region from an expression of its own and labelled it with two standards. What is the general lesson the repair drew from it?', '["A calculation fitted without a source should be retuned against the nearest published curve, and the standard names kept so that a reader knows which family it belongs to.", "A calculation can be wrong in a way no measurement repairs, because the number was never the claim. The claim was that this is what the standard says.", "A calculation labelled with a standard''s name should keep the label and widen its tolerances, so the answer it gives covers whatever the standard would have given.", "A calculation of this kind is a tolerance problem like any other."]'::jsonb, 1, 'Retuning the curve does not make the attribution true. It makes a different unsourced curve carry the same false attribution with a fresh coat of confidence on it, and the only honest repair available is to withdraw the claim.'),
  ('corrosion', 'advanced', 'module', 'm06-what-this-engine-used-to-do', 2, 'What did the pre-repair engine serve off that severity region?', '["An inspection interval and a retirement thickness, both taken from the region the stream landed in, which is why neither appears in this module today.", "A rate category band for sour streams, which sat beside the CO2 band and is the reason the category bands are held rather than merely unsourced.", "A wall shear threshold for sour service, set below the 100.000000000000 Pa used elsewhere, which was withdrawn with the region it was derived from.", "Three named material recommendations: what steel to buy, when to control hardness and when to qualify weldments."]'::jsonb, 3, 'A curve that carries a standard''s name and tells an engineer what steel to buy is not a tolerance question. The three strings are gone and none of them appears anywhere in the 783 lines of the engine source.'),
  ('corrosion', 'advanced', 'module', 'm06-what-this-engine-used-to-do', 3, 'Three measurements show what that pre-repair expression was worth. What did they find?', '["Moving its pH pivot by a whole unit left the suite green, widening a region boundary by a factor of two left the suite green, and a missing pH fell through to the hardest recommendation.", "Moving its pH pivot by a whole unit failed one case, widening a region boundary by a factor of two failed two more, and a missing pH refused with a message naming the box.", "Moving its pH pivot by a whole unit left the suite green, widening a region boundary by a factor of two failed the suite, and a missing pH returned the mildest recommendation.", "Moving its pH pivot by a whole unit left the suite green, widening a region boundary by a factor of two left it green, and a missing pH refused rather than answering."]'::jsonb, 0, 'The missing pH made the expression not-a-number, so both of its comparisons failed and it fell through to the hardest material recommendation in the file from an input nobody had supplied.'),
  ('corrosion', 'advanced', 'module', 'm06-what-this-engine-used-to-do', 4, 'The severity region is gone from this engine today. How permanent is that, and how does a caller find out?', '["It is provisional. Both fields come back false while a source is being sought, and the engine will serve the region again once a standard has been vendored beside it.", "It is permanent and silent. The two fields were removed with the function, so a caller discovers the absence by finding no such key on the returned object.", "It is current, permanent and declared. `regionProvided` is false and `materialGuidanceProvided` is false today and will keep coming back false.", "It is permanent for the region and provisional for the material guidance."]'::jsonb, 2, 'The absence arrives as a field, so a caller cannot read the gap as an unset property. The digest section that states it says in its own second line that it is not repair history.'),
  ('corrosion', 'advanced', 'module', 'm06-what-this-engine-used-to-do', 5, 'The absence of the severity region is proved three ways. What are they?', '["The region function is not exported so its type is undefined, neither standard name appears in the 783 lines of source, and no returned string in three whole screenings names either standard.", "The region function throws when it is called, the two standard names appear only inside comments, and the studio renders the absence behind the same disclosure as the held list.", "The engine exports two false flags, the golden carries no region row among its 110, and the vendored jest suite asserts that a region request refuses with a message naming the standard.", "The held list omits the region, the not-provided list names it twice, and the pin table has no row for the boundary constants of the region expression."]'::jsonb, 0, 'Each is a separate check. The two flags are how the engine states the absence, and the three proofs are how the digest established that the function and its strings have actually gone rather than been hidden.'),
  ('corrosion', 'advanced', 'module', 'm06-what-this-engine-used-to-do', 6, 'The screening threshold the sour door still uses stayed exactly where it was at 0.003500000000 bar. Why was it left alone?', '["It is validated by the golden''s sour rows, which are worked in psia while the engine works in bar, so it was the one constant the repair had grounds to keep.", "It was the only number in the region expression with a published source behind it, which is why the comparison survived the withdrawal of everything built on it.", "It sits below any value a real stream reaches, so its exact position cannot change a verdict and there was nothing for the repair to gain by moving it.", "Changing a live number without a source would have been the same mistake with the sign flipped."]'::jsonb, 3, 'The engine keeps the number, declares it held in `thresholdHeld`, and prints it in both units so nobody has to convert. Its value is measured by bisecting the sour flag.'),
  ('corrosion', 'advanced', 'module', 'm06-what-this-engine-used-to-do', 7, 'Before the repair the pH correction returned one for any pH at or below its reference. What did a sweep across pH show?', '["The rate fell by a factor of 316.227766 across that span, which is the behaviour the repair kept in place and then extended below the reference rather than refusing there at all.", "pH 2.0, 3.0, 3.5 and 4.0 all produced the identical rate to sixteen figures, while a second calculation on the same screen moved its answer four times across the same span.", "The rate moved only at the reference itself, where the factor stepped from one to its fitted value, so the box mattered at exactly one point in its own range.", "The rate rose as the water became more acid, by a decade for every two pH units, which is the direction the correction takes above the reference as well."]'::jsonb, 1, 'Two decades of hydrogen-ion activity moved the headline number by exactly nothing. A spread of zero is the whole finding, and no amount of reading the code is needed to reach it.'),
  ('corrosion', 'advanced', 'module', 'm06-what-this-engine-used-to-do', 8, 'What is the test that finds a box on a screen which has stopped reaching the answer?', '["Read the call graph from the box down to the field the reader acts on, and look for a branch where the value is replaced by a default before it arrives.", "Set the box to a value outside its range and check that the engine refuses, because a decorative box is one whose guard has been disconnected along with it.", "Walk the input across its range and print the spread of the answer.", "Compare the answer against the oracle at two settings of the box, since a route that ignores an input agrees with an independent derivation at both of them."]'::jsonb, 2, 'It is arithmetic and it takes one sweep. When one input reaches the answer by two routes and the route that decides the headline ignores it, the box on the screen is decoration.'),
  ('corrosion', 'advanced', 'module', 'm06-what-this-engine-used-to-do', 9, 'How does the pH correction behave in this engine today?', '["The rate is strictly monotonic across the whole band from pH 0 to pH 14, and the reference is now only the point at which the factor is exactly one by definition rather than by a clamp.", "The rate is monotonic above the reference and the engine returns a factor of one below it, which is the least limiting answer and is flagged in the clamps field beside the other inputs it moved.", "The rate is monotonic above the reference and the engine refuses above pH 9.000000 as well, which is where the swept band the correction was fitted on runs out.", "The rate is strictly monotonic above the reference, from 4.724817 mm/yr at pH 4.000000 to 0.014941 mm/yr at pH 9.000000, and below the reference the engine refuses."]'::jsonb, 3, 'The span is a factor of 316.227766 and every step down the column is smaller than the one above it, which the digest generator asserts on every rebuild. The refusal names the reference so that a caller can print the boundary.'),
  ('corrosion', 'advanced', 'module', 'm06-what-this-engine-used-to-do', 10, 'Before the repair a blank velocity or a blank line diameter made the mass-transfer term infinite. How far did the consequence travel?', '["An infinite transport capacity makes the series combination equal the reaction term, so the engine named reaction kinetics as controlling from an input nobody had supplied.", "An infinite transport capacity makes the series combination infinite as well, so the rate came back as not-a-number and the screening reported itself incomplete.", "An infinite transport capacity is clamped at the reaction term by the series form, so the rate was correct and only the wall shear went missing from the screen.", "An infinite transport capacity sent the engine down its no-CO2 branch, so the screen showed a rate of zero and an unbounded life under a CO2 box that still read three percent."]'::jsonb, 0, 'The rate came out several times the correct one, and a missing box in one part of the form changed the word the screen printed about the mechanism. The no-CO2 branch was reached by a different pre-repair route.'),
  ('corrosion', 'advanced', 'module', 'm06-what-this-engine-used-to-do', 11, 'Before the repair a blank temperature produced an unusual chain. What happened?', '["The fugacity became not-a-number, which propagated through the whole of the chain beneath it, so the rate and the life both came back as not-a-number and every row on the screen printed empty.", "The fugacity became infinite, which made the reaction term infinite, so the series combination sat at the transport term and the screen reported transport as controlling.", "The fugacity became not-a-number, which failed a greater-than test, which sent the engine down its no-CO2 branch: a rate of zero, a green label, an unbounded life and a passing verdict.", "The fugacity fell back to the value at the shipped default temperature, so the screen showed a plausible rate computed at a temperature nobody had entered."]'::jsonb, 2, 'Every step in that chain is individually reasonable and the end of it is a clean bill of health from nothing, printed under a CO2 box that still read three percent.'),
  ('corrosion', 'advanced', 'module', 'm06-what-this-engine-used-to-do', 12, 'The transport term returns not-a-number today rather than infinity, and the vendored gate asserts something specific about it. What?', '["That it is not-a-number at every velocity below the one at which the film-stripping threshold of 100.000000000000 Pa is first reached on that stream.", "That it is not infinity, rather than merely that it is wrong.", "That it refuses with a message naming the box, which is the same guard the whole screening door applies when any of its six required boxes is blank.", "That it agrees with the golden''s own value for a blank velocity, which the oracle reaches by marching the wall loss forward rather than by dividing."]'::jsonb, 1, 'An infinite transport capacity is a perfectly ordinary number downstream, and it is the value that makes the answer look best. Asserting the specific shape is what stops the defect returning in a form that is still wrong.'),
  ('corrosion', 'advanced', 'module', 'm06-what-this-engine-used-to-do', 13, 'Before the repair the corrosion inhibitor warning fired only when the efficiency was strictly greater than ninety percent. Why did that matter so much?', '["The strict comparison meant the warning fired on every case above ninety, so a user who typed anything at all above the default was warned twice over.", "The guard was applied to the availability rather than to the efficiency.", "The shipped efficiency of ninety was the value the correlation was fitted at.", "The studio shipped with an efficiency of exactly ninety, so the one lesson this module exists to teach was silent on the first screen every user saw."]'::jsonb, 3, 'A guard written with a strict comparison against a round number is switched off at exactly that number, and a shipped default sitting on the boundary is the likeliest value in the whole input space. The same guard was equally silent at ninety percent efficiency and fifty percent availability.'),
  ('corrosion', 'advanced', 'module', 'm06-what-this-engine-used-to-do', 14, 'Today''s corrosion inhibitor warning fires on the effective shortfall at any efficiency. What kind of change is that?', '["A design move. The old guard tested an input and the new one tests the output the warning is actually about.", "A threshold adjustment. The comparison was loosened from strictly greater to at or above, which is what lets the shipped default of exactly ninety percent through it.", "A clamp. The efficiency is now carried up to the value at which the warning fires, and the clamps field records that it was moved so a reader can see it happen.", "A rewrite of the colour logic alone."]'::jsonb, 0, 'The trigger is 0.100000 percentage points of shortfall, measured by bisecting the availability at which the warning first appears. A guard on the quantity you care about survives a change in how the inputs arrive at it.'),
  ('corrosion', 'advanced', 'module', 'm06-what-this-engine-used-to-do', 15, 'Before the repair thirteen defects planted one at a time left the validation suite entirely green, and the oracle caught none of seventeen paired moves. What was wrong with the oracle?', '["Its tolerances were set from the engine''s own output rather than from the physics, so every route passed at whatever gap the engine happened to produce on that row.", "It carried no cases at all for six of the module''s doors, so the routes it did carry were sound and the coverage around them was the part that was missing.", "Five of its routes were the engine''s own expressions written out again and one was the engine''s own line rearranged algebraically, while its docstring called that an independent re-derivation.", "It read its expected values out of the golden file at run time, so a golden regenerated from the engine made every route agree with the engine by construction."]'::jsonb, 2, 'A constant that lives in two files cannot be validated by comparing those two files. The planted defects included a sour threshold moved by a factor of ten and a mass-transfer coefficient moved by a sixth.'),
  ('corrosion', 'advanced', 'final', null, 1, 'The whole screening door returns 18 top-level fields, and the order in which it computes them is a design decision. What is computed first, and why?', '["The rate, because every other field on the screening is either derived from it or reported beside it, and the shear is one of the things reported beside it.", "The wall shear, because the rate depends on whether the corrosion inhibitor film survives it, so a shear that cannot be computed means no rate is issued at all.", "The sour comparison, because the H2S partial pressure decides which regime the stream is in and the regime decides whether a rate should be formed for it.", "The corrosion allowance arithmetic, because the design life is the only input that can make a screening incomplete and it is checked before anything is computed."]'::jsonb, 1, 'A missing density is a refusal rather than a missing row: the screening reports itself incomplete and says that the film survival check did not run. Then the rate, the credited rate beside it, the sour comparison, the regime, the withholding, the category, the life and the binding constraint.'),
  ('corrosion', 'advanced', 'final', null, 2, 'A whole screening is run with the corrosion allowance box left blank. What does a caller who checks only for a top-level error see?', '["A refusal naming the corrosion allowance box, as it does for a blank density.", "An incomplete screening, because the remaining life is one of the 18 top-level fields and a field that cannot be formed makes the whole screening incomplete.", "A withheld block naming the allowance, which is the mechanism the engine uses wherever a field cannot be issued and a reason for it can be stated.", "Nothing. The top-level error is undefined, the life is null, the withheld block is null and the screening reports itself complete."]'::jsonb, 3, 'The summary rail simply has no remaining-life row and nothing on the screen says why. That case also returns mass transfer to the wall as its binding constraint, so the screen reads as a complete answer.'),
  ('corrosion', 'advanced', 'final', null, 3, 'A whole screening is run with an allowance already consumed past its own depth. Where does the refusal end up?', '["At the top level, because a consumed allowance is the one life-door refusal the whole screening door promotes out of the field it was raised in.", "In the withheld block, alongside the reason it was raised for.", "Inside the `life` field as an error object, so a reader who checks only the outside of the result sees a normal screening.", "In the clamps field, because the consumed depth is clamped to the allowance."]'::jsonb, 2, 'A caller''s check for a top-level error passes, the remaining years are undefined, and the refusal message never reaches anyone. That is the same shape as the shear case one field along, and the shear case is the one the engine handles properly.'),
  ('corrosion', 'advanced', 'final', null, 4, 'The general lesson the whole screening door teaches is about a class of defect rather than an instance. What is it?', '["A repair that names a defect and fixes one instance of it has not removed the class. Read what a function returns rather than what its comment says it returns.", "A repair that fixes an instance has removed the class wherever the class is defined by a single shared helper, which is why the shear case covers the life case too.", "A defect of this kind is found by reading the module''s exported lists, since a field whose absence is not on either list is a field nobody has thought about yet.", "A defect of this kind is found by comparing the engine against its oracle, since a swallowed error produces a value the independent route will not reproduce."]'::jsonb, 0, 'Ask of every field whether its absence is declared or merely missing. This module declares the withdrawn region''s absence in two fields and does not declare the swallowed remaining-life refusal at all.'),
  ('corrosion', 'advanced', 'final', null, 5, 'The whole screening door takes an H2S mole fraction. A direct caller omits the key entirely. What happens?', '["The door refuses with a message saying a finite H2S mole fraction is required, which is the same message it gives for a mole fraction that is not a number.", "The door refuses with a message saying the CO2 and H2S mole fractions sum above one, because an absent fraction is compared against the total as a null.", "The door carries the H2S mole fraction from the CO2 mole fraction, so the regime comes back mixed as it does at the shipped defaults and the category is issued.", "The signature''s default of zero is used, so the H2S partial pressure is 0.000000 bar, the stream is not sour, the regime is carbonate and a category is issued."]'::jsonb, 3, 'That is the least limiting direction. An H2S mole fraction that is not a number does refuse, and the studio layer produces not-a-number from a blank box, so the live screen is protected by the layer above rather than by this default.'),
  ('corrosion', 'advanced', 'final', null, 6, 'Two mole fractions are each inside nought to one and they sum to 1.1000. What does the whole screening door do, and why does that guard exist?', '["It accepts them and clamps the larger of the two down until the sum reaches one, recording the move in the clamps field in the way it records every clamp.", "It accepts them, because each fraction passes its own range guard on the way in.", "It refuses, because their partial pressures would exceed the total pressure. Two fractions each inside their own range can still add to more than one.", "It refuses, because a CO2 mole fraction above one is outside the range guard."]'::jsonb, 2, 'The engine checks the sum against the total and not just each fraction against its own range. A sum of exactly one is accepted: two fractions of 0.600000 and 0.400000 give a partial pressure sum of 51.000427 bar against a total of 51.000427 bar and the screening runs.'),
  ('corrosion', 'advanced', 'final', null, 7, 'Which set is made up entirely of range guards this module enforces on what a caller types?', '["Nought to one on every fraction, nought to fourteen on pH, a temperature above absolute zero, and the partial-pressure sum against the total pressure.", "Nought to one on every fraction, nought to fourteen on pH, the 250.000000000000 bar fugacity cap, and the film-stripping threshold of 100.000000000000 Pa.", "A temperature above absolute zero, a positive total pressure, the published validity band of the reaction term, and the pH reference of 4.000000000000.", "Nought to fourteen on pH, a temperature above absolute zero, the Reynolds 4000.000000 branch switch, and the two H2S to CO2 transition ratios."]'::jsonb, 0, 'Every published validity band of every correlation is held rather than enforced. The cap and the thresholds are held numbers that change an answer or a word, and neither is a range guard on an input.'),
  ('corrosion', 'advanced', 'final', null, 8, 'A reader wants to know whether this engine actually uses the value it exports for a constant. What answers that, and what does not?', '["Reading the export answers it, because an exported name is the value the functions close over and there is no second copy anywhere in a module of 783 lines.", "A measurement of the behaviour answers it. Reading the export answers only what the module declares about itself.", "Comparing the export against the golden''s `heldConstants` block answers it, because the golden was generated by running the engine rather than by reading it.", "Neither answers it, which is why the digest prints both columns."]'::jsonb, 1, 'The two can differ through a second copy inside a function, a branch that never reaches the exported name, or a value transformed on the way in. Nothing in this module currently separates, and that is a result with a size attached.'),
  ('corrosion', 'advanced', 'final', null, 9, 'Sixteen of the thirty pinned constants have no export at all. What is the practical consequence?', '["For those sixteen the pin compares the golden against the digest generator instead, so the engine is out of the comparison and the pin is weaker by one copy.", "For those sixteen no pin is possible, so they are carried by the constant-free invariants and by the route independence the golden''s own file describes.", "For those sixteen the digest reads the literals out of the source.", "For those sixteen the measurement is the only column there is, which is the case the technique was built for."]'::jsonb, 3, 'The two reaction constants, the reaction fugacity exponent, the two fugacity coefficient constants, the mass-transfer coefficient and both of its exponents, the three scale constants, the pH slope, the Blasius pair, the laminar constant and the mass-transfer fugacity exponent are all reached by measurement alone.'),
  ('corrosion', 'advanced', 'final', null, 10, 'The route table gives four of its eight routes an empty cannot-check column, and the course grades four families of field. What connects the two lists?', '["Neither lets a fitted constant reach its answer, so the two lists are one property seen twice.", "Both were chosen from the golden''s seventeen whole cases, which is the block the digest compares route by route and the block the graded fields are taken from.", "Both are pinned in the digest against a literal in a third file, and a pinned quantity is one a route can check and a graded field is permitted to reach through.", "Both are exported by the engine under their own names, and an exported quantity has been declared in a way that a route and a graded field can each rely on."]'::jsonb, 0, 'The series combination, the corrosion inhibitor time average, the remaining life and the allowance shortfall are the four clear routes. The stream bookkeeping, the flow definition, the corrosion inhibitor arithmetic and the allowance arithmetic are the four graded families.'),
  ('corrosion', 'advanced', 'final', null, 11, 'What does a constant-free invariant test that a pin does not?', '["The value of a coefficient against a source, which is the one thing a pin cannot reach because a pin compares only against another copy of the number.", "The agreement between the engine and the golden, which a pin cannot reach because it compares the engine against a literal in a third file instead.", "The form of an expression rather than the value of its coefficients.", "The behaviour of the module at its boundaries, which a pin cannot reach because every pinned constant is measured away from the branch it governs."]'::jsonb, 2, 'The series residual holds to twelve figures on every row, the scale factor is exactly one at its own computed onset, the pH correction gives one decade per two pH units measured as 0.100000000000 four times over, and the mole-fraction ratio is provably free of pressure.'),
  ('corrosion', 'advanced', 'final', null, 12, 'What does this studio have to offer a reader asking whether a line is fit for service?', '["A remaining life against the stated corrosion allowance, which is the closest the module comes and is why the word integrity appears in the app''s own name.", "Nothing at all, because producing an assessment means adopting an assessment method and no such method is in this repository.", "A verdict in `meetsDesignLife`, which compares what is left against the design life.", "A withheld block naming the assessment, which is how the engine reports the quantities it declines to issue on a screening that otherwise ran to completion."]'::jsonb, 1, 'The four things a reader will look for are an inspection interval, a minimum thickness, a retirement thickness and a fitness-for-service assessment. All four are named in `NOT_PROVIDED` and the studio lists them.'),
  ('corrosion', 'advanced', 'final', null, 13, 'A stream binds on wall shear on the corrosion inhibitor film, and the reader asks whether the line is simply running too fast. What can this course say?', '["That the line is above its velocity limit, since the film-stripping threshold of 100.000000000000 Pa is where this module takes mechanical erosion to begin on the wall.", "That the question cannot be asked of a stream binding on shear, because the binding constraint reports the limit that governs and the velocity is an input rather than a limit.", "That the shear answers a chemistry question about a film. Nothing in this engine expresses a velocity limit, and the criterion that does belongs to another course entirely.", "That the wall shear and an erosional velocity are the same test in different units, so the coloured risk word answers the question as it stands."]'::jsonb, 2, 'This engine has no erosional-velocity criterion and the Casing and Tubing Design course at its Expert tier owns it. The shear here comes through this module''s own Reynolds number and this module''s own friction factor, and the line sizing course computes its own pair, which will not agree on the same pipe.'),
  ('corrosion', 'advanced', 'final', null, 14, 'A screening reports a remaining life of 4.207953 yr against a corrosion allowance of 3.175000 mm. Which part of that statement did the module compute?', '["The allowance as well, since the module forms it from the design pressure and the pipe grade before it subtracts whatever the consumed depth has taken off it.", "The division alone. The allowance, the consumed depth and the design life were all typed in, and no wall thickness and no design pressure is anywhere in the module.", "The whole statement, since the remaining life is one of the 18 top-level fields and every one of those is derived inside the engine rather than carried through it.", "Neither part, since the life rests on a rate the correlation produced and a figure resting on held constants has not been computed in any useful sense."]'::jsonb, 1, 'The arithmetic inside the door is exact and its inputs are assertions. The wall this studio is eating is not the wall the Pipeline and Line Sizing studio or the Storage Tank studio sized, and there is no link between the three.'),
  ('corrosion', 'advanced', 'final', null, 15, 'The category door is handed a negative rate. What does it do, and what makes that worth noticing?', '["It returns null, in the same way it does for a blank rate and for a rate that is not a number, so all three inputs it cannot label behave alike.", "It refuses with a message naming the rate it was handed.", "It answers rather than declining, and the word it gives is the most reassuring one it has. That is the shape to look for in any function.", "It answers with the word at the top of the scale."]'::jsonb, 2, 'Nothing upstream in the whole screening door will hand it a negative rate, so the shape does not reach the studio. It is still a function answering where it could decline, with the least alarming answer available to it.'),
  ('corrosion', 'advanced', 'final', null, 16, 'The H2S screening threshold was left where it was, and the digest says why. What argument says that tightening the category bands would not repair them either?', '["Both numbers are pinned in the digest against a literal in a third file, and a pinned number cannot be moved without the gate separating the two columns.", "Both numbers are exported by the engine, and an exported constant is part of the module''s public interface, so moving one is a change to every caller at once.", "Both numbers sit on the eleven-item held list, and an item on that list is frozen until a source for it is vendored into the repository beside the engine.", "A replacement would be just as unsourced as the original while wearing the appearance of a fix, so the screen would gain a claim of correctness it had never had."]'::jsonb, 3, 'The threshold stays at 0.003500000000 bar, is declared held in a field and is printed in both units. The bands stay at their three edges with `categoryHeld` true beside the word.'),
  ('corrosion', 'advanced', 'final', null, 17, 'The sequence that chooses a binding constraint never reads the category word. Why is that the right design?', '["The word is not available at the point the sequence runs, because the category is computed after the binding constraint in the order the screening door walks.", "The word is withheld on two of the six teaching streams, and a step that could not fire on every stream would leave those two screenings with no constraint at all.", "The word is three comparisons against three unsourced edges laid on top of a rate, so a summary ranking by it would be ranking by a rendering convention.", "The word already reflects the rate, so reading it as well as the rate would count the same evidence twice and push every stream towards the kinetics branch."]'::jsonb, 2, 'The sequence reads flags and numbers the screening has already produced: the regime, the shear against its threshold, the life against the design life, and the two rate terms against each other.'),
  ('corrosion', 'advanced', 'final', null, 18, 'Why is the binding constraint described as an answer to the question what would I change first?', '["Because the engine ranks its limits by how much each would move the rate.", "Because the engine compares each limit against the value the reader typed and names the one furthest from its own threshold, which is the easiest to move.", "Because the sequence stops at the first limit that bites, and each of the four answers implies a different first move.", "Because the constraint is chosen from the largest number on the screen, which is the figure a reader would have acted on in any case and is now named for them."]'::jsonb, 2, 'Wall shear points at the line speed, the allowance against the design life points at a specification decision, mass transfer points at velocity and line size, and the model not applying points at reading the withheld block.'),
  ('corrosion', 'advanced', 'final', null, 19, 'What is a binding constraint silent about?', '["The value it turns on, which is reported separately so the summary sentence can be rendered without a number in it wherever the studio needs it short.", "Which limit governs, because the constraint names the field that moved most rather than the limit and the reader supplies the limit from context.", "Whether the screening ran to completion, which the reader takes from a separate field because a constraint is reported whether or not the screening finished.", "Every action a reader might take, because an action needs a standard, a cost and an operating context and the module carries none of the three."]'::jsonb, 3, 'A summary that names the governing limit reads like advice because it is written in plain English. What it actually does is rank the module''s own limits against each other, and the three quantities above are all in `NOT_PROVIDED`.'),
  ('corrosion', 'advanced', 'final', null, 20, 'A line''s corrosion allowance is already fully consumed and somebody asks what allowance would reinstate the design life. What does this module do?', '["It refuses. No bisection runs, because the door declines before any verdict exists to narrow on.", "It bisects the total allowance until the design life verdict turns true, in the same way it would on any line, and returns the figure with the consumed depth included.", "It returns a negative remaining life, which is the signal a caller reads to tell a consumed line from one that still has allowance left on it to divide.", "It returns `requiredAllowanceMm` and leaves the reinstatement to the caller, since the required figure is the allowance a new line would need at that rate."]'::jsonb, 0, 'Every inversion in this module narrows a bracket until a field or a flag the engine returns turns over. Where the door declines to issue that field at all, there is nothing to narrow on, and the decline is itself the answer to the question that was asked.'),
  ('corrosion', 'advanced', 'final', null, 21, 'A remaining life and a rate category come off the same rate. Why can a capstone grade one of them and not the other?', '["A life is reported to six decimals and a category is a word, and a graded field has to be a number a tolerance can be applied to in the first place.", "A life is a division over the caller''s own numbers, while a category adds three unsourced edges on top of whatever the rate already carries.", "A life is checked against the golden''s own life rows and a category is not, so only one of the two has an independent derivation standing behind it.", "A life is exported by the engine and a category is returned only inside the whole screening, so only the life can be reached without running a screening."]'::jsonb, 1, 'A capstone here states its rate from an inspection survey, so the division has no held constant anywhere in it. The category would still carry three edges the engine declares unsourced in `categoryHeld`.'),
  ('corrosion', 'advanced', 'final', null, 22, 'A reader quotes a pressure in bar off the studio screen and a colleague quotes one from a direct engine call. Why might the two differ?', '["The studio works in bar gauge and the engine works in bar absolute, so the two differ by one atmosphere wherever the conversion has not been applied twice.", "The studio applies the fugacity coefficient to the pressure before it displays it, so a screen value is the fugacity and a direct call returns the partial pressure.", "The studio rounds every pressure to six decimals on the way out, and the engine carries the full double, so the two differ in whatever the rounding discarded.", "The studio divides a psig pressure by 14.5038 and the engine''s factor is 14.503773800722, so the two conversions separate in the sixth significant figure."]'::jsonb, 3, 'The digest lists every one of the studio''s conversions for exactly this reason: a learner reading a number off the app needs to know which layer produced it. Every graded condition in this course is stated in the engine''s units.'),
  ('corrosion', 'advanced', 'final', null, 23, 'A programme is short on effective protection. The engine''s warning names a metal-loss figure. What is that figure against?', '["The metal loss at zero corrosion inhibition, which is the uninhibited rate.", "The metal loss at the shipped default programme of 90 percent efficiency and 95 percent availability, which is the reference case the warning is written against.", "The metal loss the datasheet efficiency alone would have given, which is why availability is what limits the result.", "The metal loss the allowance can absorb over the design life, which is what turns the shortfall in percentage points into a statement about the wall."]'::jsonb, 2, 'A programme at 95 percent efficiency and 80 percent availability delivers 76.000000 percent effective protection, 19.000000 percentage points short, at 4.800000 times the datasheet metal loss. At the shipped 90 and 95 the shortfall is 4.500000 percentage points.'),
  ('corrosion', 'advanced', 'final', null, 24, 'Before the repair thirteen defects planted one at a time left the validation suite entirely green. What did the repair put in place of the routes that missed them?', '["A tighter tolerance on every route, which is what turns a comparison that admits a planted defect into one that separates on it and reports the size of the gap.", "Work split three ways with the file saying which is which: genuinely independent routes, constant-free invariants, and pins against a third copy of each constant.", "A larger golden, from 17 whole cases to 110 rows in 17 blocks, so that every door in the module carries at least one case rather than being covered by inference.", "A second oracle written by a different author, so that the two oracles and the engine make three derivations and any two of them agreeing is no longer enough."]'::jsonb, 1, 'Section 20 lists the routes with what each one cannot check, section 3 carries 30 pins measured out of the behaviour, and sections 5, 6, 7 and 13 carry the invariants. Naming which is which is what makes the coverage readable.'),
  ('corrosion', 'advanced', 'final', null, 25, 'A blank temperature once reached a green label on a screen. Which two of the current behaviours would stop that same input reaching a label at all?', '["The fugacity door returns not-a-number below absolute zero, and the category door returns negligible only for a rate that is zero or below rather than for a small one.", "The transport term returns not-a-number rather than infinity, and the binding constraint reports the model as not applying wherever a screening has come back incomplete.", "The whole screening door refuses when any of six boxes is blank and names the box, and the category door returns null rather than a word for a rate it was not given.", "The pH correction refuses below its reference, and the withheld block names the category and the life wherever the CO2 rate model has stopped describing the surface."]'::jsonb, 2, 'A typed zero is treated differently from a blank. A typed zero CO2 mole fraction is a positive assertion of no CO2 and the module withholds its category and its life, while a blank box is a question the engine cannot answer.'),
  ('corrosion', 'advanced', 'final', null, 26, 'The vendored gate asserts that a blank velocity makes the transport term not-a-number rather than merely asserting that it is wrong. Why the specific shape?', '["Because not-a-number and infinity are the same value once the series combination has been formed, so only the raw term can tell the two of them apart.", "Because the golden carries a row for a blank velocity and the comparison is made against that row, which holds not-a-number as its expected value.", "Because the whole screening door refuses on a blank velocity, so the bare term is the only place the value can be observed before the refusal is raised.", "Because infinity is the value that flatters the answer, and a gate that only required a wrong value would pass on a defect that is still wrong in the same direction."]'::jsonb, 3, 'An infinite transport capacity makes the series combination exactly equal the reaction term, so the engine named reaction kinetics as controlling from an input nobody had supplied, and the rate came out several times the correct one.'),
  ('corrosion', 'advanced', 'final', null, 27, 'A band edge moves and a held correlation constant moves. Which of the two changes a binding constraint?', '["The band edge, because the step of the sequence that tests the allowance against the design life reads the band before it reads the remaining life.", "Both, because the binding constraint is chosen from the seven numbers on the screening and the category is one of the seven it ranks between.", "Neither, because the binding constraint is chosen by a sequence of questions whose answers are all flags rather than numbers the two moves could reach.", "The correlation constant. Moving a band edge changes words and nothing else, while moving a correlation constant moves every rate and every life."]'::jsonb, 3, 'The allowance step reads the life and the design life, the transport step compares two terms of the rate, and the shear step compares the shear against a threshold. A category is not read anywhere in the sequence.'),
  ('corrosion', 'advanced', 'final', null, 28, 'A stream binds on the corrosion allowance against the design life at 1.7 yr of 20 yr, short by 30.75 mm. What has the reader still not been told?', '["What the rate was, because the constraint reports the life and the shortfall and leaves the rate to be read off a separate field on the same screening.", "What thickness to retire at and when to inspect next, because the module carries no retirement criterion and no inspection interval.", "Whether the corrosion inhibitor film survived, because the shear step sits below the allowance step in the sequence and is therefore not yet reached.", "Whether the model applies, because the applicability step is the last of the sequence."]'::jsonb, 1, 'The allowance step is reached only because the model applies and the film survives, so both of those have already been settled. The retirement thickness and the inspection interval are in `NOT_PROVIDED` and neither is anywhere in the module.'),
  ('corrosion', 'advanced', 'final', null, 29, 'The corrosion inhibitor warning trigger is 0.100000 percentage points of shortfall today and the pre-repair guard fired above 90 percent efficiency. What did the change of quantity buy?', '["A guard that fires more often, which is what makes the warning visible at the shipped defaults where the previous one had been silent about the availability.", "A guard with a pinned trigger, which is what lets the digest measure it.", "A guard on the output the warning is about, which survives a change in which of the two inputs a programme happens to be short on.", "A guard that is inclusive rather than strict, which is the whole of the repair and is why the shipped efficiency of exactly ninety now passes through it."]'::jsonb, 2, 'The old guard tested an input. The same guard was equally silent at ninety percent efficiency and fifty percent availability, which is a programme in serious trouble on the other input.'),
  ('corrosion', 'advanced', 'final', null, 30, 'The category bands are both pinned and held. What does each of those two words buy?', '["Pinned means nobody moved them quietly. Held means no source for them exists in this repository, and the second is the one that decides what can be graded.", "Pinned means they are validated against the golden''s own copy, and held means they are validated against the engine''s export, so between them the edges are checked twice.", "Pinned means the golden carries rows either side of each of them, and held means the engine declares them in a field.", "Pinned means they are measured rather than read, and held means they are enforced as a range guard."]'::jsonb, 0, 'Twelve golden category rows and a measurement by bisection establish that the edges are where the digest says they are. Neither establishes where the numbers came from, and `categoryHeld` comes back true beside the word.'),
  ('corrosion', 'advanced', 'final', null, 31, 'A programme manager reads an effective corrosion inhibition of 85.500000 percent and a band word on the same screen. Which of the two can they take to a supplier meeting as a number?', '["The band word, because it reconciles the rate against three edges the golden pins from both sides, which is more evidence than a single percentage carries.", "Both, because the screening returns them together and the studio prints the held list behind a disclosure so a reader can see what each one rests on.", "The effective figure, because it is arithmetic over two typed percentages with no correlation constant anywhere in its chain.", "Neither, because both are computed from the same stream conditions and every chain in this engine passes through at least one unsourced constant."]'::jsonb, 2, 'The shortfall on that case is 4.500000 percentage points against the datasheet figure. The word is three comparisons against three unsourced edges laid on a rate, and `categoryHeld` comes back true beside it.'),
  ('corrosion', 'advanced', 'final', null, 32, 'The binding constraint is derived from what the screening has already computed. What does it add to the pin table and to the held list?', '["Two entries to the held list, being the reporting margin of the comparable step and the ordering of the six questions the sequence walks through.", "Nothing to either. The held list stands at 11 items and the pin table at 30 constants.", "One entry to the pin table, being the controlling reporting margin, which is measured by solving for the velocity that puts the two terms a stated ratio apart.", "Four entries to the held list, one for each of the constraint types."]'::jsonb, 1, 'The held list carries 11 items and the pin table 30 constants either way. The reporting margin belongs to the controlling word, which the summary reads, so it is not something the summary brings with it.'),
  ('corrosion', 'advanced', 'final', null, 33, 'The shipped default screen carries a rate, a word, a partial pressure, an effective protection figure and a remaining life. Which of those can a capstone in this course grade?', '["The rate and the remaining life, because both are computed by the engine and both are reported to six decimals, which is the precision a graded field is checked at.", "The word and the remaining life, because the band edges are pinned and the life is a single division, so both are traceable to numbers the digest measures.", "The partial pressure and the effective protection figure, because one is a total pressure times a mole fraction and the other is arithmetic over two typed percentages.", "All five, because every figure on that screen is reproduced by the golden and the golden agrees with the engine on all seventeen of its whole cases."]'::jsonb, 2, 'The rate rests on held constants and the word adds three more on top of it. The remaining life is a division that rests on a rate, which is why a capstone states its rate from an inspection survey rather than taking it from the correlation.'),
  ('corrosion', 'advanced', 'final', null, 34, 'Set a screen that returns seven unreconciled numbers beside this engine''s screening. What do they share, and where do they part?', '["Both carry seven independent numbers. This engine''s adds a summary naming which of its own limits governs, derived from what it had already computed.", "Both print a binding constraint. This engine''s derives it from the numbers rather than from the largest of them, which is what the other ranks by.", "Both withhold a category in the sulphide regime. This engine''s adds the withheld block, which the other reports as an empty paragraph instead.", "Both refuse on a blank density. This engine''s adds the message naming the box, which is what makes the refusal actionable rather than merely present."]'::jsonb, 0, 'A screen that returns seven numbers and reconciles none of them is a screen the reader summarises by reading the largest number, and that is a property of the units rather than of the engineering.'),
  ('corrosion', 'advanced', 'final', null, 35, 'This course grades no corrosion rate the correlation produced. Which single fact is the reason?', '["The golden is synthetic, so no rate in it can be compared against a published case and the tolerance it is checked at has no meaning attached to it.", "The rate depends on the wall shear verdict, so a rate graded at one velocity would be graded at a different chain from a rate graded at another velocity.", "The studio''s psig divisor is truncated, so a rate converted through the app differs from a rate converted through the engine''s factor in the sixth figure.", "Every de Waard-Milliams constant is held, so every rate built out of them inherits an unsourced chain."]'::jsonb, 3, 'The other three statements are all true of this module and none of them is the reason. The category word inherits that chain and adds three unsourced edges of its own, which is why no graded field is a band label either.'),
  ('corrosion', 'advanced', 'final', null, 36, 'Three of these fields declare their own absence and one does not. Which is the one that does not?', '["The category in the sulphide regime, which comes back null while the withheld block names the reason and the rate is kept as a stated upper bound.", "The remaining life when the corrosion allowance box is blank, which comes back null with the screening reporting itself complete and nothing on the screen saying why.", "The effective corrosion inhibition in the oil-wet regime, which comes back null rather than zero because there is nothing to be effective against.", "The severity region on every screening, which comes back with `regionProvided` false so that a caller cannot read the gap as an unset property."]'::jsonb, 1, 'The other three absences are all declared, each in its own way. Ask of every field whether its absence is declared or merely missing, because a missing field is a question nobody asked and the reader supplies the answer from their own expectations.'),
  ('corrosion', 'advanced', 'final', null, 37, 'A reader wants to argue with a rate rather than accept it. What does this engine give them to argue with?', '["The pin table, which shows every constant the rate was built from measured out of the behaviour and compared against a literal in a third file.", "The seventeen whole golden cases, which show the engine agreeing with an independent derivation to the last bits of a double on almost every one.", "The factors reported separately, the controlling term, the credited rate beside the rate, the binding constraint and the held list behind all of it.", "The category word and `categoryHeld`, which together say how fast the loss is and how much confidence the module is prepared to put behind the word."]'::jsonb, 2, 'The whole screening door reports every factor separately rather than returning one number. The pin table and the golden are evidence about the implementation rather than about the stream in front of the reader.'),
  ('corrosion', 'advanced', 'final', null, 38, 'A sentence lifted out of an engine source comment arrives with no frame around it. How many of this module''s comment lines are written in a past tense about former behaviour?', '["Five, in a module of 783 lines, and none of them carries a repair marker.", "Eleven, one for each held item, and each one carries a repair marker naming the change that removed the behaviour it describes for a reader of the source.", "None, because the repair stripped every past-tense comment out of the module and moved the history into the digest section that carries the frame for it.", "Eight, matching the entries in the not-provided list, and each one records the behaviour that stood where the absence is now declared."]'::jsonb, 0, 'Roughly one line in 157 of the module carries a past-tense sentence about former behaviour. Engine source comments are provenance, and so are the wave recon and findings reports and the repair record vendored beside the oracle.'),
  ('corrosion', 'advanced', 'final', null, 39, 'One digest section describes behaviour this engine no longer has, and one describes a current absence that looks like history. How are the two told apart?', '["The history section is the only one that names the repair, and the withdrawal section is identified by the two flags it describes rather than by anything it says.", "The history section is the last in the file and the withdrawal section is the second, so their positions in the digest are what carry the frame for each of them.", "Neither is told apart in the digest. The frame lives in the module directory name in the course and in the lesson heading, which is where the gate looks for it.", "The history section says so in its own title and its first line and nothing follows it. The withdrawal section says in its own second line that it is not repair history."]'::jsonb, 3, 'The withdrawal is current, permanent and declared: the engine returns two false flags today and will keep doing so. Writing it as something the engine might get back is a defect.'),
  ('corrosion', 'advanced', 'final', null, 40, 'A capstone states its rate from an operator''s inspection survey. What does that survey rate still not tell the allowance arithmetic?', '["What the design life is, since a survey rate arrives without one and the remaining-life door cannot form a verdict or a required allowance without it being stated.", "Where on the line the metal is going, because the arithmetic divides an allowance by an average and this module has no localised model at all.", "Whether the corrosion inhibitor film survived, since a survey rate is measured on the wall and carries no information about the shear that produced it.", "What the units are, since a survey reports in mils a year and the door works in millimetres a year, which is the conversion the studio applies on the way out."]'::jsonb, 1, 'Stating the rate takes every held correlation constant out of the graded chain. It does not put a geometry into a number that has none, and the engine names a localised-attack rate among the things it does not provide.'),
  ('corrosion', 'advanced', 'final', null, 41, 'A caller reads a screening and finds no severity region and no material guidance. What has the engine committed itself to?', '["That both are held pending a source, in the same way the eleven items on the held list are, and that the studio will print them once one is vendored.", "That both were not computable at these conditions, which is what a caller reads from an absent field and is why the studio prints the conditions beside it.", "That both are absent by decision rather than by omission, because two fields say so and will keep saying so.", "That both belong to another course named in the scope seam."]'::jsonb, 2, 'A held item is waiting on a source and a scope gap is outside what the module attempts. This is neither, which is why it is off the held list, marked withdrawn on the not-provided list, and reported through two flags of its own as well.'),
  ('corrosion', 'advanced', 'final', null, 42, 'What is the shortest honest description of everything this module knows about integrity?', '["A corrosion allowance divided by a rate.", "A corrosion allowance divided by a rate, checked against a minimum thickness the module forms from the design pressure it was handed for the line.", "A corrosion allowance divided by a rate, with an inspection interval derived from the remaining life and the risk basis the studio carries behind a disclosure.", "A corrosion allowance divided by a rate, set against the retirement thickness that the not-provided list names as the one integrity quantity the module holds."]'::jsonb, 0, 'That is the whole arithmetic. The word invites four expectations the module cannot meet, which is why this course states the narrow reading every time the word appears.');
